"""Kaggle notebook cell -- generated by tools/make_kaggle_test_cell.py.

Do not hand-edit: regenerate from the repo instead so this stays in sync with
src/agents/dragapult_agent_v17_cpp/cpp/. Paste this whole cell into a Kaggle
notebook and run it. It writes the V17 native C++ sources into the working
directory, compiles them with the exact command the real submission uses on
Linux (see ../compile.sh / native_bridge.py's _compile_with_gxx), and then
CDLL-loads the result to catch ABI/GLIBC linking problems -- this library
exports a plain extern "C" ABI loaded via ctypes (see cpp/v17_abi.h /
native_bridge.py), not a pybind11 module, so a ctypes.CDLL load + symbol
resolution is the correct equivalent of "import the module and see if it
blows up" for this binding style.
"""

import ctypes
import subprocess
import sys
from pathlib import Path

WORK_DIR = Path("/kaggle/working/v20_cpp_test")
WORK_DIR.mkdir(parents=True, exist_ok=True)


def write_source(filename: str, content: str) -> None:
    with open(WORK_DIR / filename, "w", encoding="utf-8") as f:
        f.write(content)


write_source('v17_agent.cpp', '// Top-level C ABI entrypoint -- the ONLY translation unit in this library\n// (every other file here is header-only), so the whole build is one\n// compiler invocation: `g++ -O3 -shared -fPIC -std=c++17 -o libv17.so\n// v17_agent.cpp -ldl` (see ../compile.sh). This single-TU design is\n// deliberate: main_v17.py compiles this on first import (see ../README.md\'s\n// "Compilation" section), and a one-file build has the smallest possible\n// surface for that to go wrong on an unknown grading container.\n//\n// Two exported functions:\n//   v17_init(cg_lib_path, deck_ids, deck_len) -- once per process, at Python\n//     module import time. Loads the native engine, static card/attack\n//     tables, and the DECK constant.\n//   v17_choose_action(obs, search_begin_input, ..., out_indices, ...) --\n//     once per real Kaggle decision. Everything between entry and return\n//     stays in C++; see mcts.hpp\'s header for the call-chain shape.\n//\n// No heap object crosses this boundary in either direction: `obs` is a\n// caller-owned, pointer-passed struct (v17_abi.h) copied into an owned\n// v17::Observation immediately; the response is written into a\n// caller-provided `out_indices` buffer. There is nothing for main_v17.py to\n// free -- eliminates an entire class of cross-allocator freeing bugs by\n// construction, not by convention.\n#include <algorithm>\n#include <memory>\n#include <string>\n#include <vector>\n\n#include "card_data.hpp"\n#include "cg_engine.hpp"\n#include "mcts.hpp"\n#include "observation.hpp"\n#include "pwin_trees.hpp"\n#include "v17_abi.h"\n#include "v6_heuristic.hpp"\n#include "v6_heuristic_scores.hpp"\n#include "vectorizer.hpp"\n\nnamespace {\n\nstd::unique_ptr<cg::Engine> g_engine;\nv17::CardTable g_cards;\nstd::vector<int> g_deck;\nstd::unique_ptr<v17::V6Scorer> g_live_scorer;\nbool g_initialized = false;\n\n// V11\'s own MACRO_LOOKAHEAD_TOP_N (dragapult_policy_v11.py) -- same\n// candidate-narrowing shape, reused here for the same reason: bound the\n// branching factor before spending simulation budget.\nconstexpr int kTopNCandidates = 6;\n\n}  // namespace\n\nextern "C" {\n\n#if defined(_WIN32)\n#define V17_API __declspec(dllexport)\n#else\n#define V17_API __attribute__((visibility("default")))\n#endif\n\n// Returns 0 on success. Any nonzero return means main_v17.py must fall back\n// to the pure-Python V6 agent for the entire game -- there is no partial\n// "native for some decisions" mode once init has failed.\nV17_API int v17_init(const char* cg_lib_path, const int* deck_ids, int deck_len) {\n  try {\n    if (!cg_lib_path || !deck_ids || deck_len <= 0) return 1;\n    g_engine = std::make_unique<cg::Engine>(std::string(cg_lib_path));\n    g_cards.load(g_engine->all_card_json(), g_engine->all_attack_json());\n    g_deck.assign(deck_ids, deck_ids + deck_len);\n    g_live_scorer = std::make_unique<v17::V6Scorer>(g_cards, v17::balanced_weights());\n    g_initialized = true;\n    return 0;\n  } catch (...) {\n    g_engine.reset();\n    g_live_scorer.reset();\n    g_initialized = false;\n    return 2;\n  }\n}\n\n// Returns 0 on success (out_indices[0..*out_count) populated). Any nonzero\n// return means main_v17.py must fall back to the pure-Python V6 agent for\n// THIS decision only (the native library and live scorer state remain valid\n// for subsequent calls -- a single bad decision\'s error should not force\n// falling back for the rest of the match, matching this project\'s existing\n// try/except-per-call safety pattern in src/agents/search_lookahead_v2.py).\n//\n// out_eligible/out_search_begin_ok/out_visits (all optional/nullable, all\n// written 0 before any early return): search-budget diagnostics added for\n// the deep-search-budget experiment -- lets Python report real rollout\n// counts and distinguish "this decision didn\'t qualify for search at all"\n// from "it qualified but search_begin failed" from "it actually ran N\n// simulations", instead of only ever seeing the final chosen action.\n//\n// out_greedy_index/out_mcts_index/out_hit_terminal_reward (all optional/\n// nullable, -1/-1/0 before any early return or when not eligible): added for\n// the divergence root-cause investigation (200-game deep-search run showed\n// V17 losing to plain V6 78% of the time once search was confirmed actually\n// running) -- lets the caller see, per decision, whether MCTS\'s final pick\n// differs from V6\'s own raw greedy pick, and whether that pick was informed\n// by any rollout that reached a real (simulated) game conclusion (see\n// Mcts::kTerminalRewardThreshold\'s comment for why that matters -- state_value\'s\n// +-1,000,000 terminal reward, faithfully ported from dragapult_policy_v11.py\'s\n// one-shot-per-candidate usage, was never previously averaged with mundane\n// few-hundred-to-few-thousand heuristic scores in an unweighted mean the way\n// UCB1\'s `total_value / visits` does).\nV17_API int v17_choose_action(const V17RootObservationC* obs_c, const char* search_begin_input,\n                               int search_begin_input_len, double time_budget_ms, int* out_indices,\n                               int out_indices_cap, int* out_count, int* out_eligible,\n                               int* out_search_begin_ok, int* out_visits, int* out_greedy_index,\n                               int* out_mcts_index, int* out_hit_terminal_reward,\n                               int* out_begin_fail_count, int* out_begin_last_error) {\n  if (out_count) *out_count = 0;\n  if (out_eligible) *out_eligible = 0;\n  if (out_search_begin_ok) *out_search_begin_ok = 0;\n  if (out_visits) *out_visits = 0;\n  if (out_greedy_index) *out_greedy_index = -1;\n  if (out_mcts_index) *out_mcts_index = -1;\n  if (out_hit_terminal_reward) *out_hit_terminal_reward = 0;\n  if (out_begin_fail_count) *out_begin_fail_count = 0;\n  if (out_begin_last_error) *out_begin_last_error = 0;\n  if (!g_initialized || !g_engine || !g_live_scorer) return 10;\n  if (!obs_c || !out_indices || !out_count || out_indices_cap <= 0) return 11;\n  if (obs_c->abi_magic != V17_ABI_MAGIC) return 12;  // struct-layout mismatch between Python and this build -- never guess, hard-fail\n\n  try {\n    v17::Observation root_obs = v17::from_ctypes(*obs_c);\n\n    // Always computed: this is V6\'s own unmodified greedy choice, exactly\n    // mirroring dragapult_policy_v11.py\'s `scores = ...` (step 1) -- also\n    // the side-effecting call that updates plan_a_/plan_b_/use_support_ for\n    // this decision (only when context == MAIN; see v6_heuristic.hpp).\n    std::vector<double> scores = g_live_scorer->raw_scores(root_obs);\n    std::vector<int> greedy_choice = v17::V6Scorer::select_top(root_obs, scores);\n    std::vector<int> final_choice = greedy_choice;\n    if (out_greedy_index && !greedy_choice.empty()) *out_greedy_index = greedy_choice[0];\n\n    bool eligible_for_search = (root_obs.context == v17::enums::CTX_MAIN) && (root_obs.maxCount == 1) &&\n                                (static_cast<int>(root_obs.options.size()) >= 2) && search_begin_input &&\n                                (search_begin_input_len > 0);\n    if (out_eligible) *out_eligible = eligible_for_search ? 1 : 0;\n\n    if (eligible_for_search) {\n      std::vector<int> ranked(scores.size());\n      for (size_t i = 0; i < scores.size(); ++i) ranked[i] = static_cast<int>(i);\n      std::stable_sort(ranked.begin(), ranked.end(),\n                        [&](int a, int b) { return scores[static_cast<size_t>(a)] > scores[static_cast<size_t>(b)]; });\n\n      // Candidate pruning (2026-08-14 stabilization -- see mcts.hpp\'s header\n      // notes): V6 marks deliberately-bad moves with negative scores (-1 /\n      // UNNECESSARY) and leaves unmodeled options (notably plain end-turn)\n      // at the 0 default. Neither belongs in the search tree when V6 sees a\n      // genuinely good action available (score >= 1000): at the observed\n      // 8-12% divergence win rates, letting a 0-scored END or a\n      // negative-scored option win on noisy rollout means is pure downside\n      // (the MCTS:[END]-vs-V6:[PLAY] bucket, 60 occurrences / 11.7% WR).\n      // The greedy top-1 is always candidates[0] -- Mcts::search\'s contract\n      // (it is the margin-gating baseline).\n      std::vector<int> candidates;\n      const double best_score = scores[static_cast<size_t>(ranked[0])];\n      for (size_t i = 0; i < ranked.size() && static_cast<int>(candidates.size()) < kTopNCandidates; ++i) {\n        const double s = scores[static_cast<size_t>(ranked[i])];\n        if (!candidates.empty() && (s < 0.0 || (best_score >= 1000.0 && s <= 0.0))) break;  // sorted descending -- nothing later qualifies either\n        candidates.push_back(ranked[i]);\n      }\n\n      if (static_cast<int>(candidates.size()) >= 2) {\n        v17::McTsConfig cfg;\n        cfg.time_budget_ms = time_budget_ms;\n        v17::Mcts mcts(*g_engine, g_cards, g_deck, cfg);\n        std::string sbi(search_begin_input, static_cast<size_t>(search_begin_input_len));\n        // B2/PUCT priors: the candidates\' own raw V6 greedy scores.\n        std::vector<double> candidate_scores;\n        candidate_scores.reserve(candidates.size());\n        for (int ci : candidates) candidate_scores.push_back(scores[static_cast<size_t>(ci)]);\n        int visits = 0;\n        bool begin_ok = false;\n        bool hit_terminal = false;\n        int begin_fail_count = 0;\n        int begin_last_error = 0;\n        int chosen = mcts.search(root_obs, candidates, sbi, *g_live_scorer, &visits, &begin_ok, &hit_terminal,\n                                  &begin_fail_count, &begin_last_error, &candidate_scores);\n        if (out_begin_fail_count) *out_begin_fail_count = begin_fail_count;\n        if (out_begin_last_error) *out_begin_last_error = begin_last_error;\n        if (out_search_begin_ok) *out_search_begin_ok = begin_ok ? 1 : 0;\n        if (out_visits) *out_visits = visits;\n        if (out_hit_terminal_reward) *out_hit_terminal_reward = hit_terminal ? 1 : 0;\n        if (out_mcts_index) *out_mcts_index = chosen;\n        if (chosen >= 0) {\n          final_choice = {chosen};\n        }\n        // else: `final_choice` stays the plain-greedy result computed above --\n        // the same safety net as dragapult_policy_v11.py\'s\n        // `_macro_lookahead_choice` returning None.\n      }\n      // Fewer than 2 surviving candidates: every alternative was one V6\n      // itself vetoed -- searching would only create chances to override a\n      // correct greedy pick with noise. Play greedy.\n    }\n\n    int n = std::min(static_cast<int>(final_choice.size()), out_indices_cap);\n    for (int i = 0; i < n; ++i) out_indices[i] = final_choice[static_cast<size_t>(i)];\n    *out_count = n;\n    return 0;\n  } catch (...) {\n    return 13;\n  }\n}\n\n// V20 debug/parity export: vectorize the given root observation with the C++\n// vectorizer and run the embedded B1 forest on it. Local parity testing only\n// (Python compares this against src/ml/vectorizer.py + xgboost on the same\n// live observation) -- never on the decision path. `out_features` (nullable,\n// capacity 87) also returns the raw feature vector so a probability mismatch\n// can be localized to the exact feature.\nV17_API int v20_debug_pwin(const V17RootObservationC* obs_c, double* out_pwin, float* out_features) {\n  if (!g_initialized || !obs_c || !out_pwin) return 1;\n  if (obs_c->abi_magic != V17_ABI_MAGIC) return 2;\n  try {\n    v17::Observation obs = v17::from_ctypes(*obs_c);\n    float features[v20::kVecFeatureCount];\n    v20::vectorize_observation(obs, g_cards, features);\n    if (out_features) {\n      for (int i = 0; i < v20::kVecFeatureCount; ++i) out_features[i] = features[i];\n    }\n    *out_pwin = v20::pwin_predict(features);\n    return 0;\n  } catch (...) {\n    return 3;\n  }\n}\n\n}  // extern "C"\n')
write_source('v17_abi.h', '// Shared binary contract between main_v17.py\'s `ctypes.Structure` definitions\n// and this C++ library. This is the ONE root-decision observation per real\n// Kaggle call -- Python already has `obs_dict` as parsed dicts (it never\n// touched JSON text at all, kaggle_environments handed it a dict), so it\n// flattens the handful of fields V6\'s heuristic/MCTS need into this struct\n// and passes it by pointer via ctypes. No JSON parsing happens for this path\n// on either side.\n//\n// (Contrast with json_extract.hpp: that parser exists ONLY for the DLL\'s\n// SearchStep replies generated *inside* the C++ MCTS loop, which Python never\n// sees -- a structurally different problem with a structurally different\n// answer. See ../README.md.)\n//\n// CRITICAL: every field here must stay in the exact same order and exact\n// same integer width on both sides. `#pragma pack(push, 1)` (mirrored by\n// `_pack_ = 1` on the Python ctypes.Structure classes in py_wrapper.py)\n// removes compiler-dependent padding as a variable entirely -- do not remove\n// either side\'s pack pragma without updating the other. `abi_magic` is a\n// cheap first line of defense: if the two sides\' struct layouts ever drift\n// out of sync, v17_choose_action rejects the call immediately instead of\n// silently reading garbage into the heuristic.\n//\n// Every "absent/None" optional int field uses -1 as its sentinel. Checked\n// against the real schema (cg/api.py) that every field using this sentinel\n// has a value range of either "always >= 0" (index/count/id fields) or a\n// small non-negative enum starting at 0 (e.g. SpecialConditionType 0..4) --\n// -1 never collides with a real value anywhere this sentinel is used.\n#pragma once\n\n#include <cstdint>\n\n#define V17_ABI_MAGIC 0x56323041  // "V20A" -- bumped from V18\'s 0x56313841 when the\n                                  // B1-vectorizer fields were appended (turnActionCount,\n                                  // oppDiscardCount, opponent statuses)\n\n#define V17_MAX_ENERGIES 12\n#define V17_MAX_TOOLS 4\n#define V17_MAX_PRE_EVO 3\n#define V17_MAX_BENCH 8\n#define V17_MAX_HAND 20\n#define V17_MAX_DISCARD 64\n#define V17_MAX_DECK_DISTINCT 60\n#define V17_MAX_PRIZE 8\n#define V17_MAX_OPTIONS 200\n#define V17_MAX_OUT_INDICES 16\n#define V17_MAX_SELECT_DECK 60\n#define V17_MAX_LOOKING 20\n#define V17_MAX_OPP_POOL 60\n\n#pragma pack(push, 1)\n\ntypedef struct {\n  int32_t present;    // 0 if this slot has no Pokemon at all (empty active/bench slot)\n  int32_t faceDown;   // 1 if present but identity hidden (opponent\'s face-down Pokemon) -- all fields below are 0 in that case\n  int32_t id;\n  int32_t serial;\n  int32_t hp;\n  int32_t maxHp;\n  int32_t appearThisTurn;\n  int32_t energiesCount;\n  int32_t energies[V17_MAX_ENERGIES];\n  int32_t energyCardsCount;\n  int32_t energyCardIds[V17_MAX_ENERGIES];\n  int32_t toolsCount;\n  int32_t toolIds[V17_MAX_TOOLS];\n  int32_t preEvoCount;\n  int32_t preEvoIds[V17_MAX_PRE_EVO];\n} V17PokemonC;\n\ntypedef struct {\n  int32_t id;\n  int32_t serial;\n  int32_t playerIndex;\n} V17CardC;\n\ntypedef struct {\n  int32_t type;   // OptionType (cg.api.OptionType integer value)\n  int32_t number;\n  int32_t area;\n  int32_t index;\n  int32_t playerIndex;\n  int32_t toolIndex;\n  int32_t energyIndex;\n  int32_t count;\n  int32_t inPlayArea;\n  int32_t inPlayIndex;\n  int32_t attackId;\n  int32_t cardId;\n  int32_t serial;\n  int32_t specialConditionType;\n} V17OptionC;\n\ntypedef struct {\n  int32_t abi_magic;  // must equal V17_ABI_MAGIC -- checked first, see file header\n\n  int32_t myIndex;\n  int32_t turn;\n  int32_t firstPlayer;\n  int32_t supporterPlayed;\n  int32_t stadiumPlayed;\n  int32_t energyAttached;\n  int32_t retreated;\n  int32_t result;          // -1 if the match has not concluded\n  int32_t stadiumCardId;   // 0 if no stadium in play\n\n  int32_t selectType;\n  int32_t context;         // SelectContext\n  int32_t minCount;\n  int32_t maxCount;\n  int32_t remainDamageCounter;\n  int32_t remainEnergyCost;\n  int32_t contextCardId;   // 0 if select.contextCard is None\n  int32_t effectCardId;    // 0 if select.effect is None\n\n  int32_t myDeckCount;\n  int32_t oppDeckCount;\n  int32_t myPrizeCount;\n  int32_t oppPrizeCount;\n  int32_t oppHandCount;\n\n  int32_t myPoisoned;\n  int32_t myBurned;\n  int32_t myAsleep;\n  int32_t myParalyzed;\n  int32_t myConfused;\n\n  // Bookkeeping computed in Python (see main_v17.py\'s small ported preamble,\n  // mirroring dragapult_policy_v6.py\'s pre_turn_log scan) -- both require\n  // state that persists across calls within our own turn, which is cheap and\n  // already implemented/validated in the existing Python module, so it is\n  // NOT reimplemented in C++. Nothing about this data changes per simulated\n  // MCTS branch (it describes what happened before this decision, not a\n  // hypothetical future), so computing it once in Python per real decision\n  // is correct and free of the performance concerns that motivate C++ for\n  // the rollout loop itself.\n  int32_t preKo;\n  int32_t noItem;\n\n  V17PokemonC myActive;\n  V17PokemonC oppActive;\n\n  int32_t myBenchCount;\n  V17PokemonC myBench[V17_MAX_BENCH];\n  int32_t oppBenchCount;\n  V17PokemonC oppBench[V17_MAX_BENCH];\n\n  int32_t myHandCount;\n  V17CardC myHand[V17_MAX_HAND];\n\n  int32_t myDiscardCount;\n  V17CardC myDiscard[V17_MAX_DISCARD];\n\n  // select.deck: cards visible via a deck-facing select (cg.api.py:\n  // "None unless selecting cards from the deck") -- NOT only the initial\n  // deck-declare exchange (which never reaches this struct at all, handled\n  // entirely in Python before native_choose_action is called), but ALSO any\n  // later decision where AreaType.DECK options reference these cards\n  // directly (e.g. a search-your-deck effect). get_card()-equivalent\n  // resolution for AreaType.DECK indexes into this list.\n  int32_t selectDeckCount;\n  V17CardC selectDeck[V17_MAX_SELECT_DECK];\n\n  // Actual prize-card objects when their identity is currently visible (a\n  // taken/revealed prize) -- NOT the same as myPrizeGuessIds below (an\n  // identity GUESS used for hidden-info determinization). A None/face-down\n  // slot is encoded as id=0 (a real card id is never 0 in this game\'s ID\n  // space) at its ORIGINAL index position -- positions must stay aligned\n  // with what Option.index refers to, entries are never skipped/compacted.\n  int32_t myPrizeCardsCount;\n  V17CardC myPrizeCards[V17_MAX_PRIZE];\n\n  // state.looking: cards currently being revealed by a search/look effect\n  // (cg/api.py: "None if not looking cards"). Same id=0 sentinel/positional\n  // rule as myPrizeCards above.\n  int32_t lookingCount;\n  V17CardC looking[V17_MAX_LOOKING];\n\n  // Sparse (card_id, remaining_count) pairs describing "what\'s still in my\n  // deck", per V6\'s own set_card_counts bookkeeping (DECK minus everything\n  // currently visible minus the prize guess below) -- computed in Python\n  // (cheap, O(deck size)=60 per real decision) and handed over already\n  // resolved, rather than re-deriving DECK-minus-visible in C++.\n  int32_t deckDistinctCount;\n  int32_t deckIds[V17_MAX_DECK_DISTINCT];\n  int32_t deckCounts[V17_MAX_DECK_DISTINCT];\n\n  // Our own prize-card-identity guess (fixed once at the deck-declare call,\n  // held constant thereafter, exactly mirroring V6\'s self.prize) -- used both\n  // by the heuristic\'s hand_score() logic and as the `your_prize` argument to\n  // the native engine\'s SearchBegin.\n  int32_t myPrizeGuessCount;\n  int32_t myPrizeGuessIds[V17_MAX_PRIZE];\n\n  int32_t optionCount;\n  V17OptionC options[V17_MAX_OPTIONS];\n\n  // Block A1 (V18): the ready-to-deal sampling pool for the OPPONENT\'s hidden\n  // zones (deck + hand + prizes), already fully resolved by Python: the\n  // classified archetype\'s canonical 60-card list (or our own deck as the\n  // mirror fallback) minus every opponent card visible on the board and in\n  // their discard. The native side must use it VERBATIM (shuffle + deal, pad\n  // with the energy filler if short) -- no further visible-board subtraction,\n  // that has already been done. Count 0 => Python could not build a pool\n  // (defensive); the native side then falls back to V17\'s own mirror-minus-\n  // visible-board logic.\n  int32_t oppHiddenPoolCount;\n  int32_t oppHiddenPoolIds[V17_MAX_OPP_POOL];\n\n  // V20 (B1 learned eval): observation fields the P(win) model was trained\n  // on that earlier ABIs never carried.\n  int32_t turnActionCount;\n  int32_t oppDiscardCount;\n  int32_t oppPoisoned;\n  int32_t oppBurned;\n  int32_t oppAsleep;\n  int32_t oppParalyzed;\n  int32_t oppConfused;\n} V17RootObservationC;\n\n#pragma pack(pop)\n')
write_source('json_extract.hpp', '// Narrow, single-pass JSON field extractor -- NOT a general JSON library.\n//\n// Why this exists at all (see ../README.md "Forward model" section for the\n// full architecture): the competition engine\'s `SearchBegin`/`SearchStep`\n// exports only return JSON strings (there is no binary struct ABI available\n// -- that\'s a constraint of the shipped `cg.dll`/`libcg.so`, not a choice\n// made here). Those calls happen entirely inside the C++ MCTS loop, native\n// engine call after native engine call, with Python never in the loop --\n// so *something* in C++ has to read the reply, every single simulated step.\n//\n// Deliberately NOT a generic recursive-descent-to-heap-tree parser: there is\n// no `Value` type, no `std::map`/`std::vector` tree, nothing allocated until\n// the caller asks for one specific leaf (an int/bool/string). Every function\n// here operates on `std::string_view`s into a buffer the CALLER owns (see\n// cg_engine.hpp -- the DLL\'s transient reply is copied into an owned\n// std::string once, immediately; every std::string_view derived from it here\n// must not outlive that owning std::string, exactly like any other\n// string_view usage). The only real allocations are the final extracted\n// leaves (an int has none; a string leaf allocates one std::string, same as\n// any normal C++ code reading a value out of a buffer).\n//\n// Scope: handles the actual JSON this engine emits (objects, arrays,\n// strings with the standard backslash escapes + \\uXXXX, numbers, true/\n// false/null). Not a conformance-tested general parser -- it only needs to\n// correctly read well-formed engine output, matching the schema in\n// cg/api.py\'s dataclasses (this project\'s own ground-truth reference).\n#pragma once\n\n#include <cstdlib>\n#include <optional>\n#include <string>\n#include <string_view>\n#include <utility>\n#include <vector>\n\nnamespace jx {\n\ninline size_t skip_ws(std::string_view s, size_t pos) {\n  while (pos < s.size()) {\n    char c = s[pos];\n    if (c == \' \' || c == \'\\t\' || c == \'\\n\' || c == \'\\r\') {\n      ++pos;\n    } else {\n      break;\n    }\n  }\n  return pos;\n}\n\n// Returns the raw span of exactly one JSON value starting at `pos` (after\n// skipping leading whitespace), plus the index just past it. Balances\n// {}/[]/quoted-strings (including escaped quotes/braces inside strings, so a\n// card name or log text containing a literal \'"\' or \'{\' never desyncs the\n// scan). Returns nullopt only on truncated/malformed input.\ninline std::optional<std::pair<std::string_view, size_t>> read_value(std::string_view s, size_t pos) {\n  pos = skip_ws(s, pos);\n  if (pos >= s.size()) return std::nullopt;\n  size_t start = pos;\n  char c = s[pos];\n\n  if (c == \'{\' || c == \'[\') {\n    char open = c;\n    char close = (c == \'{\') ? \'}\' : \']\';\n    int depth = 0;\n    bool in_str = false;\n    bool esc = false;\n    for (; pos < s.size(); ++pos) {\n      char ch = s[pos];\n      if (in_str) {\n        if (esc) {\n          esc = false;\n        } else if (ch == \'\\\\\') {\n          esc = true;\n        } else if (ch == \'"\') {\n          in_str = false;\n        }\n        continue;\n      }\n      if (ch == \'"\') {\n        in_str = true;\n        continue;\n      }\n      if (ch == open) {\n        ++depth;\n      } else if (ch == close) {\n        --depth;\n        if (depth == 0) {\n          ++pos;\n          break;\n        }\n      }\n    }\n    if (depth != 0) return std::nullopt;  // truncated\n    return std::make_pair(s.substr(start, pos - start), pos);\n  }\n\n  if (c == \'"\') {\n    bool esc = false;\n    ++pos;\n    bool closed = false;\n    for (; pos < s.size(); ++pos) {\n      char ch = s[pos];\n      if (esc) {\n        esc = false;\n        continue;\n      }\n      if (ch == \'\\\\\') {\n        esc = true;\n        continue;\n      }\n      if (ch == \'"\') {\n        ++pos;\n        closed = true;\n        break;\n      }\n    }\n    if (!closed) return std::nullopt;\n    return std::make_pair(s.substr(start, pos - start), pos);\n  }\n\n  // number / true / false / null: run until a structural delimiter.\n  while (pos < s.size()) {\n    char ch = s[pos];\n    if (ch == \',\' || ch == \'}\' || ch == \']\' || ch == \' \' || ch == \'\\t\' || ch == \'\\n\' || ch == \'\\r\') break;\n    ++pos;\n  }\n  if (pos == start) return std::nullopt;\n  return std::make_pair(s.substr(start, pos - start), pos);\n}\n\n// `obj` must be a JSON object span (as returned by read_value, e.g. from a\n// prior object_member/array_items call). Returns the raw value span for\n// `key`, or nullopt if absent/null/not an object -- callers treat "absent"\n// and "null" identically throughout this project (matching the engine\'s own\n// documented "new fields may be appended" schema-evolution note).\ninline std::optional<std::string_view> object_member(std::string_view obj, std::string_view key) {\n  size_t pos = skip_ws(obj, 0);\n  if (pos >= obj.size() || obj[pos] != \'{\') return std::nullopt;\n  ++pos;\n  pos = skip_ws(obj, pos);\n  if (pos < obj.size() && obj[pos] == \'}\') return std::nullopt;  // empty object\n\n  while (pos < obj.size()) {\n    pos = skip_ws(obj, pos);\n    if (pos >= obj.size() || obj[pos] != \'"\') return std::nullopt;  // malformed\n    auto key_res = read_value(obj, pos);\n    if (!key_res) return std::nullopt;\n    std::string_view raw_key = key_res->first;\n    pos = key_res->second;\n\n    pos = skip_ws(obj, pos);\n    if (pos >= obj.size() || obj[pos] != \':\') return std::nullopt;\n    ++pos;\n\n    auto val_res = read_value(obj, pos);\n    if (!val_res) return std::nullopt;\n    std::string_view raw_val = val_res->first;\n    pos = val_res->second;\n\n    // Strip the surrounding quotes from the key. Every key in this schema is\n    // a plain ASCII identifier (field name) -- never escaped -- so no\n    // unescaping is needed here (unlike string VALUES, see unescape_string).\n    std::string_view unquoted_key = (raw_key.size() >= 2) ? raw_key.substr(1, raw_key.size() - 2) : raw_key;\n    if (unquoted_key == key) {\n      if (raw_val == "null") return std::nullopt;\n      return raw_val;\n    }\n\n    pos = skip_ws(obj, pos);\n    if (pos < obj.size() && obj[pos] == \',\') {\n      ++pos;\n      continue;\n    }\n    break;  // \'}\' or end of buffer\n  }\n  return std::nullopt;\n}\n\n// `arr` must be a JSON array span. Returns the raw value span of each\n// top-level element, in order.\ninline std::vector<std::string_view> array_items(std::string_view arr) {\n  std::vector<std::string_view> out;\n  size_t pos = skip_ws(arr, 0);\n  if (pos >= arr.size() || arr[pos] != \'[\') return out;\n  ++pos;\n  pos = skip_ws(arr, pos);\n  if (pos < arr.size() && arr[pos] == \']\') return out;\n\n  while (pos < arr.size()) {\n    auto v = read_value(arr, pos);\n    if (!v) break;\n    out.push_back(v->first);\n    pos = skip_ws(arr, v->second);\n    if (pos < arr.size() && arr[pos] == \',\') {\n      ++pos;\n      continue;\n    }\n    break;\n  }\n  return out;\n}\n\ninline bool is_null_or_absent(const std::optional<std::string_view>& v) {\n  return !v.has_value() || *v == "null";\n}\n\ninline int to_int(const std::optional<std::string_view>& v, int default_value = 0) {\n  if (is_null_or_absent(v)) return default_value;\n  // std::string_view is not guaranteed NUL-terminated; std::stoi needs a\n  // std::string. These leaves are short (a handful of digits), so the copy\n  // is cheap and this stays portable across standard library versions that\n  // don\'t yet have full <charconv> floating support (see long_double/double\n  // note below) rather than reaching for std::from_chars everywhere.\n  try {\n    return std::stoi(std::string(*v));\n  } catch (...) {\n    return default_value;\n  }\n}\n\ninline long long to_int64(const std::optional<std::string_view>& v, long long default_value = 0) {\n  if (is_null_or_absent(v)) return default_value;\n  try {\n    return std::stoll(std::string(*v));\n  } catch (...) {\n    return default_value;\n  }\n}\n\ninline double to_double(const std::optional<std::string_view>& v, double default_value = 0.0) {\n  if (is_null_or_absent(v)) return default_value;\n  try {\n    return std::stod(std::string(*v));\n  } catch (...) {\n    return default_value;\n  }\n}\n\ninline bool to_bool(const std::optional<std::string_view>& v, bool default_value = false) {\n  if (is_null_or_absent(v)) return default_value;\n  if (*v == "true") return true;\n  if (*v == "false") return false;\n  return default_value;\n}\n\n// `v` includes the surrounding quotes (a raw string-value span from\n// read_value/object_member). Strips them and resolves backslash escapes.\ninline std::string to_unescaped_string(const std::optional<std::string_view>& v, const std::string& default_value = "") {\n  if (is_null_or_absent(v)) return default_value;\n  std::string_view s = *v;\n  if (s.size() < 2 || s.front() != \'"\' || s.back() != \'"\') return default_value;\n  s = s.substr(1, s.size() - 2);\n\n  std::string out;\n  out.reserve(s.size());\n  for (size_t i = 0; i < s.size(); ++i) {\n    char c = s[i];\n    if (c != \'\\\\\' || i + 1 >= s.size()) {\n      out.push_back(c);\n      continue;\n    }\n    char esc = s[++i];\n    switch (esc) {\n      case \'"\': out.push_back(\'"\'); break;\n      case \'\\\\\': out.push_back(\'\\\\\'); break;\n      case \'/\': out.push_back(\'/\'); break;\n      case \'b\': out.push_back(\'\\b\'); break;\n      case \'f\': out.push_back(\'\\f\'); break;\n      case \'n\': out.push_back(\'\\n\'); break;\n      case \'r\': out.push_back(\'\\r\'); break;\n      case \'t\': out.push_back(\'\\t\'); break;\n      case \'u\': {\n        if (i + 4 >= s.size()) break;\n        unsigned code = 0;\n        for (int k = 0; k < 4; ++k) {\n          char h = s[i + 1 + k];\n          code <<= 4;\n          if (h >= \'0\' && h <= \'9\') code |= static_cast<unsigned>(h - \'0\');\n          else if (h >= \'a\' && h <= \'f\') code |= static_cast<unsigned>(h - \'a\' + 10);\n          else if (h >= \'A\' && h <= \'F\') code |= static_cast<unsigned>(h - \'A\' + 10);\n        }\n        i += 4;\n        if (code < 0x80) {\n          out.push_back(static_cast<char>(code));\n        } else if (code < 0x800) {\n          out.push_back(static_cast<char>(0xC0 | (code >> 6)));\n          out.push_back(static_cast<char>(0x80 | (code & 0x3F)));\n        } else {\n          out.push_back(static_cast<char>(0xE0 | (code >> 12)));\n          out.push_back(static_cast<char>(0x80 | ((code >> 6) & 0x3F)));\n          out.push_back(static_cast<char>(0x80 | (code & 0x3F)));\n        }\n        break;\n      }\n      default:\n        out.push_back(esc);\n    }\n  }\n  return out;\n}\n\n}  // namespace jx\n')
write_source('card_data.hpp', '// Static card/attack metadata tables -- the C++ analogue of V6\'s\n// `_card_table`/`_attack_table` (dragapult_policy_v6.py: `{c.cardId: c for c\n// in all_card_data()}` / `{a.attackId: a for a in all_attack()}`). Parsed\n// ONCE at v17_init() time from the engine\'s `AllCard()`/`AllAttack()` exports\n// (not inside the hot MCTS loop -- this is a startup cost, same as the\n// Python agents already pay via `all_card_data()`/`all_attack()` at import\n// time), using the same json_extract.hpp helpers as everywhere else.\n#pragma once\n\n#include <string>\n#include <unordered_map>\n#include <utility>\n#include <vector>\n\n#include "json_extract.hpp"\n\nnamespace v17 {\n\nstruct CardData {\n  int cardId = 0;\n  std::string name;\n  int cardType = -1;      // CardType\n  int retreatCost = 0;\n  int hp = 0;\n  int weakness = -1;      // EnergyType, -1 if null\n  int resistance = -1;    // EnergyType, -1 if null\n  int energyType = 0;     // EnergyType\n  bool basic = false;\n  bool stage1 = false;\n  bool stage2 = false;\n  bool ex = false;\n  bool megaEx = false;\n  bool tera = false;\n  bool aceSpec = false;\n  std::vector<int> attacks;  // attack IDs\n};\n\nstruct AttackData {\n  int attackId = 0;\n  std::string name;\n  int damage = 0;\n  std::vector<int> energies;  // EnergyType cost list\n};\n\nclass CardTable {\n public:\n  void load(const std::string& all_card_json, const std::string& all_attack_json) {\n    for (auto item : jx::array_items(all_card_json)) {\n      CardData c;\n      c.cardId = jx::to_int(jx::object_member(item, "cardId"), 0);\n      c.name = jx::to_unescaped_string(jx::object_member(item, "name"), "");\n      c.cardType = jx::to_int(jx::object_member(item, "cardType"), -1);\n      c.retreatCost = jx::to_int(jx::object_member(item, "retreatCost"), 0);\n      c.hp = jx::to_int(jx::object_member(item, "hp"), 0);\n      c.weakness = jx::to_int(jx::object_member(item, "weakness"), -1);\n      c.resistance = jx::to_int(jx::object_member(item, "resistance"), -1);\n      c.energyType = jx::to_int(jx::object_member(item, "energyType"), 0);\n      c.basic = jx::to_bool(jx::object_member(item, "basic"), false);\n      c.stage1 = jx::to_bool(jx::object_member(item, "stage1"), false);\n      c.stage2 = jx::to_bool(jx::object_member(item, "stage2"), false);\n      c.ex = jx::to_bool(jx::object_member(item, "ex"), false);\n      c.megaEx = jx::to_bool(jx::object_member(item, "megaEx"), false);\n      c.tera = jx::to_bool(jx::object_member(item, "tera"), false);\n      c.aceSpec = jx::to_bool(jx::object_member(item, "aceSpec"), false);\n      auto attacks = jx::object_member(item, "attacks");\n      if (attacks.has_value()) {\n        for (auto a : jx::array_items(*attacks)) c.attacks.push_back(jx::to_int(a, 0));\n      }\n      cards_[c.cardId] = std::move(c);\n    }\n\n    for (auto item : jx::array_items(all_attack_json)) {\n      AttackData a;\n      a.attackId = jx::to_int(jx::object_member(item, "attackId"), 0);\n      a.name = jx::to_unescaped_string(jx::object_member(item, "name"), "");\n      a.damage = jx::to_int(jx::object_member(item, "damage"), 0);\n      auto energies = jx::object_member(item, "energies");\n      if (energies.has_value()) {\n        for (auto e : jx::array_items(*energies)) a.energies.push_back(jx::to_int(e, 0));\n      }\n      attacks_[a.attackId] = std::move(a);\n    }\n  }\n\n  // Returns a default-constructed CardData (cardId 0, empty name) for an\n  // unknown id rather than throwing -- callers that index this table with a\n  // card id sourced from live engine data should never hit this, but a\n  // silent-default is safer than a crash mid-MCTS-rollout given the engine\'s\n  // own documented "new fields/cards may be appended" schema-evolution note.\n  const CardData& card(int id) const {\n    static const CardData kEmpty;\n    auto it = cards_.find(id);\n    return it == cards_.end() ? kEmpty : it->second;\n  }\n\n  const AttackData& attack(int id) const {\n    static const AttackData kEmpty;\n    auto it = attacks_.find(id);\n    return it == attacks_.end() ? kEmpty : it->second;\n  }\n\n  bool has_card(int id) const { return cards_.find(id) != cards_.end(); }\n\n private:\n  std::unordered_map<int, CardData> cards_;\n  std::unordered_map<int, AttackData> attacks_;\n};\n\n}  // namespace v17\n')
write_source('cg_engine.hpp', '// Thin C++ binding to the official competition engine (`cg.dll` / `libcg.so`\n// / `libcg.dylib`), loaded dynamically at runtime via the OS loader (LoadLibrary\n// / dlopen) rather than link-time linkage against an import library.\n//\n// Deliberate design choice, not an oversight: this project has the engine\'s\n// full C++ header source under data/official/ptcg_engine/ (see\n// ENGINE_CLONE_LOOKAHEAD_AUDIT.md), but that source is licensed\n// "competition-use-only, not open source... don\'t share or republish it"\n// (data/official/ptcg_engine/ptcgProgram 22/README.md /\n// LICENSES/LicenseRef-PTCG-ABC-Competition-Use-Only.txt). Recompiling that\n// source into a new binary we then bundle into a Kaggle submission would be a\n// real redistribution/derivative-work question this project has no authority\n// to resolve unilaterally. Calling the ALREADY-COMPILED, ALREADY-SHIPPED\n// `cg.dll`/`libcg.so` through its public `extern "C"` export table\n// (Export.cpp) is exactly what the official Python `cg` package already does\n// via ctypes -- this is the same sanctioned client/library boundary, just\n// implemented in C++ instead of ctypes, with nothing about the engine itself\n// re-linked, recompiled, or redistributed.\n//\n// Only the subset of exports our agent actually needs is declared: the\n// *search sandbox* API (AgentStart/SearchBegin/SearchStep/SearchEnd), plus\n// AllCard/AllAttack for static card data, plus GameInitialize. We deliberately\n// do NOT bind BattleStart/Select/GetBattleData/BattleFinish -- those drive the\n// LIVE match, which only the Kaggle grading harness (or the local `cg.game`\n// dev harness) is supposed to touch; our agent only ever advises via the\n// disposable search sandbox and returns an index list, exactly like the\n// existing Python agents (src/agents/search_lookahead_v2.py) already do.\n#pragma once\n\n#include <cstdint>\n#include <stdexcept>\n#include <string>\n#include <vector>\n\n#include "json_extract.hpp"\n\n#if defined(_WIN32)\n#define WIN32_LEAN_AND_MEAN\n// Without NOMINMAX, <windows.h> #defines min/max as function-like macros,\n// which silently rewrites every std::max(...)/std::min(...) call anywhere\n// else in this project\'s headers into nonsense and fails to compile with a\n// misleading "illegal token on right side of \'::\'" (MSVC C2589) far from\n// this file. Confirmed by hitting exactly that error empirically before\n// adding this.\n#define NOMINMAX\n#include <windows.h>\n#else\n#include <dlfcn.h>\n#endif\n\nnamespace cg {\n\n// Mirrors cg/api.py\'s ApiResult -> SearchState -> Observation JSON shape at\n// the raw-string level; parsing into typed structs happens in observation.hpp.\n// Every SearchBegin/SearchStep call returns one JSON string of this shape:\n//   {"state": {"observation": {...}, "searchId": N} | null, "error": E}\nstruct RawSearchResult {\n  bool ok = false;\n  int error = 0;\n  std::string observation_json;  // only valid if ok\n  long long search_id = 0;       // only valid if ok\n};\n\nclass EngineLoadError : public std::runtime_error {\n public:\n  explicit EngineLoadError(const std::string& msg) : std::runtime_error(msg) {}\n};\n\n// Loads and exposes the native library. One instance should live for the\n// whole process lifetime (mirrors the Python `cg` package\'s own module-level\n// `lib` and the sanctioned "AgentStart once per process, never destroy"\n// usage documented in ENGINE_CLONE_LOOKAHEAD_AUDIT.md Part 3 -- there is no\n// exported "destroy agent sandbox" function, so we never attempt one either).\nclass Engine {\n public:\n  explicit Engine(const std::string& lib_path) {\n#if defined(_WIN32)\n    handle_ = reinterpret_cast<void*>(LoadLibraryA(lib_path.c_str()));\n#else\n    handle_ = dlopen(lib_path.c_str(), RTLD_NOW | RTLD_LOCAL);\n#endif\n    if (!handle_) {\n      throw EngineLoadError("failed to load native engine library at: " + lib_path);\n    }\n\n    agent_start_ = resolve<AgentStartFn>("AgentStart");\n    search_begin_ = resolve<SearchBeginFn>("SearchBegin");\n    search_step_ = resolve<SearchStepFn>("SearchStep");\n    search_end_ = resolve<SearchEndFn>("SearchEnd");\n    search_release_ = resolve<SearchReleaseFn>("SearchRelease");\n    all_card_ = resolve<AllCardFn>("AllCard");\n    all_attack_ = resolve<AllAttackFn>("AllAttack");\n\n    // Deliberately NOT calling GameInitialize() here, even though it\'s a\n    // real exported function -- confirmed by hitting this empirically (a\n    // "buffer full, capacity:7" native-side failure) while compiling and\n    // smoke-testing this against a real VS Build Tools install: `lib_path`\n    // here always resolves to the SAME physical cg.dll/libcg.so file the\n    // Python `cg` package already loaded (native_bridge.py\'s own top-level\n    // `import cg` runs before this constructor is ever reached -- see that\n    // module\'s docstring), and the OS loader gives a second LoadLibrary/\n    // dlopen call on an already-loaded module a handle to the SAME image,\n    // sharing all static/global state. cg/sim.py already calls\n    // GameInitialize() exactly once at that import; calling it again here\n    // re-runs whatever one-time global setup it does against\n    // already-initialized state and corrupts it. This makes GameInitialize\n    // itself effectively load-order-coupled to Python -- documented here\n    // rather than silently relied upon, since it\'s the one place this\n    // binding is NOT fully independent of the Python side already having\n    // run.\n    agent_ptr_ = agent_start_();\n    if (!agent_ptr_) {\n      throw EngineLoadError("AgentStart() returned null -- native engine failed to allocate a search sandbox");\n    }\n  }\n\n  Engine(const Engine&) = delete;\n  Engine& operator=(const Engine&) = delete;\n\n  ~Engine() {\n    // No AgentFinish export exists (confirmed by source trace,\n    // ENGINE_CLONE_LOOKAHEAD_AUDIT.md Part 3) -- there is nothing to release\n    // here beyond unloading the library itself, which we deliberately also\n    // skip: this Engine is meant to live for the whole process, and freeing\n    // the library at static-destructor time on process exit is unnecessary\n    // risk (destructor ordering vs. any OS-level atexit cleanup the DLL\n    // itself may have registered) for zero benefit.\n  }\n\n  std::string all_card_json() {\n    const char* p = all_card_();\n    return p ? std::string(p) : std::string("[]");\n  }\n\n  std::string all_attack_json() {\n    const char* p = all_attack_();\n    return p ? std::string(p) : std::string("[]");\n  }\n\n  // `serialized`/`count` is the opaque `search_begin_input` token from the\n  // live Observation (docs/search_api.md §1) -- NOT JSON, a raw byte buffer\n  // the engine itself minted. The four "predicted" id lists are our\n  // determinization guess for hidden zones (V6Heuristic::determinize_* ports\n  // the same deck/prize bookkeeping V6/V11 already do in Python).\n  RawSearchResult search_begin(const std::string& serialized,\n                                const std::vector<int>& my_deck,\n                                const std::vector<int>& my_prize,\n                                const std::vector<int>& enemy_deck,\n                                const std::vector<int>& enemy_prize,\n                                const std::vector<int>& enemy_hand,\n                                const std::vector<int>& enemy_active,\n                                bool manual_coin) {\n    const char* raw = search_begin_(\n        agent_ptr_, serialized.data(), static_cast<int>(serialized.size()),\n        const_cast<int*>(my_deck.data()), const_cast<int*>(my_prize.data()),\n        const_cast<int*>(enemy_deck.data()), const_cast<int*>(enemy_prize.data()),\n        const_cast<int*>(enemy_hand.data()), const_cast<int*>(enemy_active.data()),\n        manual_coin ? 1 : 0);\n    // `raw` points into the engine\'s own persistent per-ApiData JsonBuilder\n    // buffer (Export.cpp: `data->jsonBuilder.buf.c_str()`) -- it is\n    // overwritten by the NEXT call into this same agent_ptr_, never owned by\n    // us and never to be freed here. Copy immediately into a std::string.\n    return parse_raw_result(raw ? std::string(raw) : std::string());\n  }\n\n  RawSearchResult search_step(long long search_id, const std::vector<int>& select) {\n    const char* raw = search_step_(agent_ptr_, search_id, const_cast<int*>(select.data()),\n                                    static_cast<int>(select.size()));\n    return parse_raw_result(raw ? std::string(raw) : std::string());\n  }\n\n  void search_end() { search_end_(agent_ptr_); }\n\n  void search_release(long long search_id) { search_release_(agent_ptr_, search_id); }\n\n private:\n  using AgentStartFn = void* (*)();\n  using SearchBeginFn = const char* (*)(void*, const char*, int, int*, int*, int*, int*, int*, int*, int);\n  using SearchStepFn = const char* (*)(void*, long long, int*, int);\n  using SearchEndFn = void (*)(void*);\n  using SearchReleaseFn = void (*)(void*, long long);\n  using AllCardFn = const char* (*)();\n  using AllAttackFn = const char* (*)();\n\n  template <typename FnPtr>\n  FnPtr resolve(const char* symbol) {\n#if defined(_WIN32)\n    void* addr = reinterpret_cast<void*>(GetProcAddress(reinterpret_cast<HMODULE>(handle_), symbol));\n#else\n    void* addr = dlsym(handle_, symbol);\n#endif\n    if (!addr) {\n      throw EngineLoadError(std::string("native engine library missing expected export: ") + symbol);\n    }\n    return reinterpret_cast<FnPtr>(addr);\n  }\n\n  // Parses the fixed ApiResult envelope ({"state": {...}|null, "error": E})\n  // using the narrow jx:: extractor (see json_extract.hpp) -- two top-level\n  // fields plus one nested lookup, no tree allocation. The *inner*\n  // observation substring is copied out into its own owned std::string here\n  // (required: it points into `raw`, which is a local about to go out of\n  // scope) and handed to observation.hpp\'s from_search_json only when/if the\n  // caller actually needs typed fields -- MCTS\'s cheap tree-policy checks\n  // (e.g. "did the turn end") often only need `error`/`search_id`.\n  static RawSearchResult parse_raw_result(const std::string& raw) {\n    RawSearchResult r;\n    if (raw.empty()) {\n      r.ok = false;\n      r.error = -1;\n      return r;\n    }\n    r.error = jx::to_int(jx::object_member(raw, "error"), 0);\n    auto state = jx::object_member(raw, "state");\n    if (r.error != 0 || !state.has_value()) {\n      r.ok = false;\n      return r;\n    }\n    r.search_id = jx::to_int64(jx::object_member(*state, "searchId"), 0);\n    auto obs = jx::object_member(*state, "observation");\n    if (!obs.has_value()) {\n      r.ok = false;\n      r.error = -2;  // malformed reply: "state" present but no "observation" -- treat as a hard failure, never guess\n      return r;\n    }\n    r.ok = true;\n    r.observation_json = std::string(*obs);  // owned copy -- `raw` (and thus `*obs`\'s backing memory) goes out of scope on return\n    return r;\n  }\n\n  void* handle_ = nullptr;\n  void* agent_ptr_ = nullptr;\n\n  AgentStartFn agent_start_ = nullptr;\n  SearchBeginFn search_begin_ = nullptr;\n  SearchStepFn search_step_ = nullptr;\n  SearchEndFn search_end_ = nullptr;\n  SearchReleaseFn search_release_ = nullptr;\n  AllCardFn all_card_ = nullptr;\n  AllAttackFn all_attack_ = nullptr;\n};\n\n}  // namespace cg\n')
write_source('deck_tracking.hpp', '// Recomputes Observation::deckCounts for a simulated MCTS node -- the native\n// analogue of dragapult_policy_v6.py\'s `set_card_counts` (DECK constant\n// minus everything currently visible). Used ONLY for nodes built via\n// from_search_json (i.e. every node inside the MCTS tree); the ROOT\n// observation already carries an exact deckCounts computed in Python by\n// literally reusing DragapultPolicy\'s own bookkeeping (main_v17.py), so this\n// is never called on it.\n//\n// Deliberately simpler than the Python original: V6\'s `add_card_count` dedupes\n// by card `serial` because it scans several OVERLAPPING zone listings\n// (hand/discard/bench/active/stadium/looking/select.effect) where the same\n// physical card could otherwise be double-subtracted. Here we only subtract\n// from disjoint zones (active/bench/hand/discard/stadium) -- a card cannot\n// physically be in two of those at once -- so no dedup bookkeeping is needed.\n// The one accepted gap: `select.effect` (a card mid-resolution, sometimes not\n// yet reflected in any zone listing) is not subtracted, so deckCounts can be\n// off by one for the exact instant an effect card is resolving. This affects\n// only a few minor hand_score terms (Buddy_Buddy_Poffin/Crispin energy-count\n// checks) deep inside rollout branches, never the root decision -- an\n// accepted approximation in the same spirit as the preKo/noItem/myPrizeGuess\n// snapshot-vs-rederive tradeoff documented in observation.hpp.\n#pragma once\n\n#include <unordered_map>\n#include <utility>\n#include <vector>\n\n#include "observation.hpp"\n\nnamespace v17 {\n\ninline void recompute_deck_counts(Observation& o, const std::vector<int>& deck_const) {\n  std::unordered_map<int, int> counts;\n  counts.reserve(deck_const.size());\n  for (int id : deck_const) counts[id] += 1;\n\n  auto subtract = [&](int id) {\n    auto it = counts.find(id);\n    if (it != counts.end() && it->second > 0) it->second -= 1;\n  };\n  auto subtract_pokemon = [&](const Pokemon& p) {\n    if (!p.present || p.faceDown) return;\n    subtract(p.id);\n    for (int eid : p.energyCardIds) subtract(eid);\n    for (int tid : p.toolIds) subtract(tid);\n    for (int pid : p.preEvoIds) subtract(pid);\n  };\n\n  subtract_pokemon(o.myActive);\n  for (const auto& p : o.myBench) subtract_pokemon(p);\n  for (const auto& c : o.myHand) subtract(c.id);\n  for (const auto& c : o.myDiscard) subtract(c.id);\n  if (o.stadiumCardId != 0) subtract(o.stadiumCardId);\n  for (int id : o.myPrizeGuess) subtract(id);\n\n  o.deckCounts.clear();\n  o.deckCounts.reserve(counts.size());\n  for (const auto& kv : counts) o.deckCounts.emplace_back(kv.first, kv.second);\n}\n\n}  // namespace v17\n')
write_source('observation.hpp', '// Internal, owning C++ representation of one decision point -- the native\n// analogue of cg/api.py\'s `Observation`/`SelectData`/`State`/`PlayerState`/\n// `Pokemon`/`Card` dataclasses, trimmed to exactly the fields V6Heuristic and\n// Mcts actually read (skills text, log detail, etc. are never needed by the\n// ported scoring logic and are omitted).\n//\n// Two independent ways to build one, matching the two places decisions come\n// from (see ../README.md\'s call-chain diagram):\n//   - from_ctypes(): the ONE real per-decision root observation, already\n//     flattened by Python (see v17_abi.h) -- a pure field copy, no parsing.\n//   - from_search_json(): every simulated node inside the MCTS tree, built\n//     from the native engine\'s own JSON reply via json_extract.hpp. Never\n//     touches Python.\n//\n// Every member is a plain owned value (int/bool/std::string/std::vector) --\n// nothing here stores a std::string_view, so an instance is safe to keep\n// alive independently of whatever buffer it was parsed from.\n#pragma once\n\n#include <optional>\n#include <string>\n#include <utility>\n#include <vector>\n\n#include "json_extract.hpp"\n#include "v17_abi.h"\n\nnamespace v17 {\n\nstruct Pokemon {\n  bool present = false;\n  bool faceDown = false;\n  int id = 0;\n  int serial = 0;\n  int hp = 0;\n  int maxHp = 0;\n  bool appearThisTurn = false;\n  std::vector<int> energies;        // EnergyType per attached energy unit\n  std::vector<int> energyCardIds;   // card id per attached energy card\n  std::vector<int> toolIds;\n  std::vector<int> preEvoIds;\n};\n\nstruct Card {\n  int id = 0;\n  int serial = 0;\n  int playerIndex = -1;\n};\n\nstruct Option {\n  int type = -1;\n  int number = -1;\n  int area = -1;\n  int index = -1;\n  int playerIndex = -1;\n  int toolIndex = -1;\n  int energyIndex = -1;\n  int count = -1;\n  int inPlayArea = -1;\n  int inPlayIndex = -1;\n  int attackId = -1;\n  int cardId = -1;\n  int serial = -1;\n  int specialConditionType = -1;\n};\n\nstruct Observation {\n  int myIndex = 0;\n  int turn = 0;\n  int firstPlayer = -1;\n  bool supporterPlayed = false;\n  bool stadiumPlayed = false;\n  bool energyAttached = false;\n  bool retreated = false;\n  int result = -1;  // -1 == not finished; 0/1 == winner index; 2 == draw\n  int stadiumCardId = 0;\n\n  int selectType = -1;\n  int context = -1;\n  int minCount = 0;\n  int maxCount = 0;\n  int remainDamageCounter = 0;\n  int remainEnergyCost = 0;\n  int contextCardId = 0;\n  int effectCardId = 0;\n\n  int myDeckCount = 0;\n  int oppDeckCount = 0;\n  int myPrizeCount = 0;\n  int oppPrizeCount = 0;\n  int oppHandCount = 0;\n\n  bool myPoisoned = false;\n  bool myBurned = false;\n  bool myAsleep = false;\n  bool myParalyzed = false;\n  bool myConfused = false;\n\n  // V20 additions -- required by vectorizer.hpp (B1 learned eval): fields\n  // the B1 model was trained on that V17/V18 never carried.\n  int turnActionCount = 0;\n  int oppDiscardCount = 0;\n  bool oppPoisoned = false;\n  bool oppBurned = false;\n  bool oppAsleep = false;\n  bool oppParalyzed = false;\n  bool oppConfused = false;\n\n  // Carried-forward from the real decision point, NOT re-derived per\n  // simulated turn inside a rollout -- see README.md\'s "accepted\n  // approximations" section for why (mirrors the project\'s existing\n  // documented-limitation style, e.g. the shared-RNG caveat in\n  // ENGINE_CLONE_LOOKAHEAD_AUDIT.md Part 5).\n  bool preKo = false;\n  bool noItem = false;\n\n  Pokemon myActive;\n  Pokemon oppActive;\n  std::vector<Pokemon> myBench;\n  std::vector<Pokemon> oppBench;\n  std::vector<Card> myHand;\n  std::vector<Card> myDiscard;\n\n  // select.deck: present whenever a decision offers AreaType.DECK options\n  // (cg/api.py: "None unless selecting cards from the deck") -- covers both\n  // the deck-declare exchange (never reaches this struct, handled in Python\n  // before native_choose_action) and later deck-searching effects, which DO\n  // reach here. get_card()-equivalent resolution for AreaType.DECK indexes\n  // into this.\n  std::vector<Card> selectDeck;\n\n  // AreaType.PRIZE / AreaType.LOOKING resolution targets. A `Card{id=0,...}`\n  // entry at some index means that slot is face-down/unrevealed there (see\n  // v17_abi.h) -- positions are never compacted, so Option.index still lines\n  // up with the real cg.api zone.\n  std::vector<Card> myPrizeCards;\n  std::vector<Card> looking;\n\n  // (card_id, remaining_count) pairs. Recomputed fresh at every node (root\n  // AND every rollout step) from the DECK constant minus everything\n  // currently visible in THIS node minus myPrizeGuess -- see\n  // v6_heuristic.hpp\'s recompute_deck_counts(), which is what actually\n  // fills this in; from_ctypes/from_search_json only carry the raw\n  // ingredients (hand/bench/discard/active), not this derived field.\n  std::vector<std::pair<int, int>> deckCounts;\n\n  // Fixed once at the real deck-declare moment (root only), then carried\n  // forward unchanged through every rollout branch -- see the preKo/noItem\n  // comment above; the same "snapshot, don\'t re-derive mid-rollout"\n  // approximation applies here for the same reason (a real prize-take\n  // during a simulated branch, which would reveal one identity, is not\n  // modeled).\n  std::vector<int> myPrizeGuess;\n\n  // Block A1 (V18): pre-resolved opponent hidden-zone sampling pool (see\n  // v17_abi.h\'s oppHiddenPoolIds comment). Root only -- like myPrizeGuess,\n  // never re-derived inside a rollout; empty means "not provided, use the\n  // legacy mirror-minus-visible-board fallback".\n  std::vector<int> oppHiddenPool;\n\n  std::vector<Option> options;\n};\n\ninline Pokemon pokemon_from_ctypes(const V17PokemonC& p) {\n  Pokemon out;\n  out.present = p.present != 0;\n  out.faceDown = p.faceDown != 0;\n  out.id = p.id;\n  out.serial = p.serial;\n  out.hp = p.hp;\n  out.maxHp = p.maxHp;\n  out.appearThisTurn = p.appearThisTurn != 0;\n  for (int i = 0; i < p.energiesCount && i < V17_MAX_ENERGIES; ++i) out.energies.push_back(p.energies[i]);\n  for (int i = 0; i < p.energyCardsCount && i < V17_MAX_ENERGIES; ++i) out.energyCardIds.push_back(p.energyCardIds[i]);\n  for (int i = 0; i < p.toolsCount && i < V17_MAX_TOOLS; ++i) out.toolIds.push_back(p.toolIds[i]);\n  for (int i = 0; i < p.preEvoCount && i < V17_MAX_PRE_EVO; ++i) out.preEvoIds.push_back(p.preEvoIds[i]);\n  return out;\n}\n\ninline Observation from_ctypes(const V17RootObservationC& c) {\n  Observation o;\n  o.myIndex = c.myIndex;\n  o.turn = c.turn;\n  o.firstPlayer = c.firstPlayer;\n  o.supporterPlayed = c.supporterPlayed != 0;\n  o.stadiumPlayed = c.stadiumPlayed != 0;\n  o.energyAttached = c.energyAttached != 0;\n  o.retreated = c.retreated != 0;\n  o.result = c.result;\n  o.stadiumCardId = c.stadiumCardId;\n\n  o.selectType = c.selectType;\n  o.context = c.context;\n  o.minCount = c.minCount;\n  o.maxCount = c.maxCount;\n  o.remainDamageCounter = c.remainDamageCounter;\n  o.remainEnergyCost = c.remainEnergyCost;\n  o.contextCardId = c.contextCardId;\n  o.effectCardId = c.effectCardId;\n\n  o.myDeckCount = c.myDeckCount;\n  o.oppDeckCount = c.oppDeckCount;\n  o.myPrizeCount = c.myPrizeCount;\n  o.oppPrizeCount = c.oppPrizeCount;\n  o.oppHandCount = c.oppHandCount;\n\n  o.myPoisoned = c.myPoisoned != 0;\n  o.myBurned = c.myBurned != 0;\n  o.myAsleep = c.myAsleep != 0;\n  o.myParalyzed = c.myParalyzed != 0;\n  o.myConfused = c.myConfused != 0;\n\n  o.turnActionCount = c.turnActionCount;\n  o.oppDiscardCount = c.oppDiscardCount;\n  o.oppPoisoned = c.oppPoisoned != 0;\n  o.oppBurned = c.oppBurned != 0;\n  o.oppAsleep = c.oppAsleep != 0;\n  o.oppParalyzed = c.oppParalyzed != 0;\n  o.oppConfused = c.oppConfused != 0;\n\n  o.preKo = c.preKo != 0;\n  o.noItem = c.noItem != 0;\n\n  o.myActive = pokemon_from_ctypes(c.myActive);\n  o.oppActive = pokemon_from_ctypes(c.oppActive);\n\n  for (int i = 0; i < c.myBenchCount && i < V17_MAX_BENCH; ++i) o.myBench.push_back(pokemon_from_ctypes(c.myBench[i]));\n  for (int i = 0; i < c.oppBenchCount && i < V17_MAX_BENCH; ++i) o.oppBench.push_back(pokemon_from_ctypes(c.oppBench[i]));\n\n  for (int i = 0; i < c.myHandCount && i < V17_MAX_HAND; ++i) {\n    o.myHand.push_back(Card{c.myHand[i].id, c.myHand[i].serial, c.myHand[i].playerIndex});\n  }\n  for (int i = 0; i < c.myDiscardCount && i < V17_MAX_DISCARD; ++i) {\n    o.myDiscard.push_back(Card{c.myDiscard[i].id, c.myDiscard[i].serial, c.myDiscard[i].playerIndex});\n  }\n  for (int i = 0; i < c.selectDeckCount && i < V17_MAX_SELECT_DECK; ++i) {\n    o.selectDeck.push_back(Card{c.selectDeck[i].id, c.selectDeck[i].serial, c.selectDeck[i].playerIndex});\n  }\n  for (int i = 0; i < c.myPrizeCardsCount && i < V17_MAX_PRIZE; ++i) {\n    o.myPrizeCards.push_back(Card{c.myPrizeCards[i].id, c.myPrizeCards[i].serial, c.myPrizeCards[i].playerIndex});\n  }\n  for (int i = 0; i < c.lookingCount && i < V17_MAX_LOOKING; ++i) {\n    o.looking.push_back(Card{c.looking[i].id, c.looking[i].serial, c.looking[i].playerIndex});\n  }\n\n  for (int i = 0; i < c.myPrizeGuessCount && i < V17_MAX_PRIZE; ++i) o.myPrizeGuess.push_back(c.myPrizeGuessIds[i]);\n\n  for (int i = 0; i < c.oppHiddenPoolCount && i < V17_MAX_OPP_POOL; ++i) o.oppHiddenPool.push_back(c.oppHiddenPoolIds[i]);\n\n  for (int i = 0; i < c.deckDistinctCount && i < V17_MAX_DECK_DISTINCT; ++i) {\n    o.deckCounts.emplace_back(c.deckIds[i], c.deckCounts[i]);\n  }\n\n  for (int i = 0; i < c.optionCount && i < V17_MAX_OPTIONS; ++i) {\n    const V17OptionC& op = c.options[i];\n    Option out;\n    out.type = op.type;\n    out.number = op.number;\n    out.area = op.area;\n    out.index = op.index;\n    out.playerIndex = op.playerIndex;\n    out.toolIndex = op.toolIndex;\n    out.energyIndex = op.energyIndex;\n    out.count = op.count;\n    out.inPlayArea = op.inPlayArea;\n    out.inPlayIndex = op.inPlayIndex;\n    out.attackId = op.attackId;\n    out.cardId = op.cardId;\n    out.serial = op.serial;\n    out.specialConditionType = op.specialConditionType;\n    o.options.push_back(out);\n  }\n\n  return o;\n}\n\nnamespace detail {\n\ninline Pokemon parse_pokemon(std::optional<std::string_view> node) {\n  Pokemon p;\n  if (!node.has_value()) {\n    p.present = false;\n    return p;\n  }\n  p.present = true;\n  // A present-but-face-down Pokemon serializes as a JSON `null` inside the\n  // active array (cg/api.py: "None if the card is facedown"); object_member\n  // already normalizes null -> nullopt for the id/serial/hp lookups below,\n  // so a face-down Pokemon naturally comes out as id=0/serial=0/hp=0 -- we\n  // still record faceDown explicitly so callers don\'t mistake that for a\n  // real 0-HP Pokemon.\n  bool has_id = jx::object_member(*node, "id").has_value();\n  p.faceDown = !has_id;\n  p.id = jx::to_int(jx::object_member(*node, "id"), 0);\n  p.serial = jx::to_int(jx::object_member(*node, "serial"), 0);\n  p.hp = jx::to_int(jx::object_member(*node, "hp"), 0);\n  p.maxHp = jx::to_int(jx::object_member(*node, "maxHp"), 0);\n  p.appearThisTurn = jx::to_bool(jx::object_member(*node, "appearThisTurn"), false);\n\n  auto energies = jx::object_member(*node, "energies");\n  if (energies.has_value()) {\n    for (auto item : jx::array_items(*energies)) p.energies.push_back(jx::to_int(item, 0));\n  }\n  auto energy_cards = jx::object_member(*node, "energyCards");\n  if (energy_cards.has_value()) {\n    for (auto item : jx::array_items(*energy_cards)) p.energyCardIds.push_back(jx::to_int(jx::object_member(item, "id"), 0));\n  }\n  auto tools = jx::object_member(*node, "tools");\n  if (tools.has_value()) {\n    for (auto item : jx::array_items(*tools)) p.toolIds.push_back(jx::to_int(jx::object_member(item, "id"), 0));\n  }\n  auto pre_evo = jx::object_member(*node, "preEvolution");\n  if (pre_evo.has_value()) {\n    for (auto item : jx::array_items(*pre_evo)) p.preEvoIds.push_back(jx::to_int(jx::object_member(item, "id"), 0));\n  }\n  return p;\n}\n\n// `arr_val` is the raw span of a `list[Pokemon]`/`list[Card]` JSON array\n// (e.g. `state.players[i].bench`), read via object_member on the enclosing\n// PlayerState object.\ninline std::optional<Pokemon> parse_pokemon_slot0(std::optional<std::string_view> arr_val) {\n  if (!arr_val.has_value()) return std::nullopt;\n  auto items = jx::array_items(*arr_val);\n  if (items.empty()) return std::nullopt;  // array present but empty -> no active Pokemon at all\n  return parse_pokemon(items[0]);\n}\n\ninline std::vector<Pokemon> parse_pokemon_list(std::optional<std::string_view> arr_val) {\n  std::vector<Pokemon> out;\n  if (!arr_val.has_value()) return out;\n  for (auto item : jx::array_items(*arr_val)) out.push_back(parse_pokemon(item));\n  return out;\n}\n\ninline std::vector<Card> parse_card_list(std::optional<std::string_view> arr_val) {\n  std::vector<Card> out;\n  if (!arr_val.has_value()) return out;\n  for (auto item : jx::array_items(*arr_val)) {\n    Card c;\n    c.id = jx::to_int(jx::object_member(item, "id"), 0);\n    c.serial = jx::to_int(jx::object_member(item, "serial"), 0);\n    c.playerIndex = jx::to_int(jx::object_member(item, "playerIndex"), -1);\n    out.push_back(c);\n  }\n  return out;\n}\n\n}  // namespace detail\n\n// Parses one Observation JSON object (as returned by a SearchBegin/SearchStep\n// call, already unwrapped from its ApiResult envelope by cg_engine.hpp) into\n// our internal struct. `carry_forward` supplies the fields this node cannot\n// derive on its own (preKo/noItem/myPrizeGuess -- see the Observation struct\n// comments above for why those are intentionally snapshotted rather than\n// re-derived per simulated step) plus `myIndex`, which the engine\'s\n// Observation reports per the CURRENT acting player -- when a simulated\n// branch reaches a decision point for the OPPONENT instead of us, the\n// caller (mcts.hpp) is responsible for recognizing that via\n// `current.yourIndex` and routing to opponent-modeling logic rather than\n// calling this with the wrong `carry_forward.myIndex`.\n//\n// Returns nullopt if `select` is null (this only happens on the very first\n// deck-declare call in a real game, which the caller never routes into the\n// search sandbox in the first place -- treated as a hard "shouldn\'t happen"\n// rather than silently guessed).\ninline std::optional<Observation> from_search_json(const std::string& obs_json, const Observation& carry_forward) {\n  auto select = jx::object_member(obs_json, "select");\n  auto current = jx::object_member(obs_json, "current");\n  if (!select.has_value() || !current.has_value()) return std::nullopt;\n\n  Observation o;\n  o.preKo = carry_forward.preKo;\n  o.noItem = carry_forward.noItem;\n  o.myPrizeGuess = carry_forward.myPrizeGuess;\n\n  o.myIndex = jx::to_int(jx::object_member(*current, "yourIndex"), carry_forward.myIndex);\n  o.turn = jx::to_int(jx::object_member(*current, "turn"), 0);\n  o.turnActionCount = jx::to_int(jx::object_member(*current, "turnActionCount"), 0);  // V20: B1 feature\n  o.firstPlayer = jx::to_int(jx::object_member(*current, "firstPlayer"), -1);\n  o.supporterPlayed = jx::to_bool(jx::object_member(*current, "supporterPlayed"), false);\n  o.stadiumPlayed = jx::to_bool(jx::object_member(*current, "stadiumPlayed"), false);\n  o.energyAttached = jx::to_bool(jx::object_member(*current, "energyAttached"), false);\n  o.retreated = jx::to_bool(jx::object_member(*current, "retreated"), false);\n  o.result = jx::to_int(jx::object_member(*current, "result"), -1);\n\n  auto stadium_arr = jx::object_member(*current, "stadium");\n  o.stadiumCardId = 0;\n  if (stadium_arr.has_value()) {\n    auto items = jx::array_items(*stadium_arr);\n    if (!items.empty()) o.stadiumCardId = jx::to_int(jx::object_member(items[0], "id"), 0);\n  }\n\n  o.selectType = jx::to_int(jx::object_member(*select, "type"), -1);\n  o.context = jx::to_int(jx::object_member(*select, "context"), -1);\n  o.minCount = jx::to_int(jx::object_member(*select, "minCount"), 0);\n  o.maxCount = jx::to_int(jx::object_member(*select, "maxCount"), 0);\n  o.remainDamageCounter = jx::to_int(jx::object_member(*select, "remainDamageCounter"), 0);\n  o.remainEnergyCost = jx::to_int(jx::object_member(*select, "remainEnergyCost"), 0);\n  auto context_card = jx::object_member(*select, "contextCard");\n  o.contextCardId = context_card.has_value() ? jx::to_int(jx::object_member(*context_card, "id"), 0) : 0;\n  auto effect = jx::object_member(*select, "effect");\n  o.effectCardId = effect.has_value() ? jx::to_int(jx::object_member(*effect, "id"), 0) : 0;\n\n  auto players = jx::object_member(*current, "players");\n  std::vector<std::string_view> player_states = players.has_value() ? jx::array_items(*players) : std::vector<std::string_view>{};\n  int my_idx = o.myIndex;\n  int opp_idx = 1 - my_idx;\n\n  if (static_cast<size_t>(my_idx) < player_states.size() && static_cast<size_t>(opp_idx) < player_states.size()) {\n    std::string_view my_ps = player_states[my_idx];\n    std::string_view opp_ps = player_states[opp_idx];\n\n    auto my_active_slot = detail::parse_pokemon_slot0(jx::object_member(my_ps, "active"));\n    o.myActive = my_active_slot.value_or(Pokemon{});\n    auto opp_active_slot = detail::parse_pokemon_slot0(jx::object_member(opp_ps, "active"));\n    o.oppActive = opp_active_slot.value_or(Pokemon{});\n\n    o.myBench = detail::parse_pokemon_list(jx::object_member(my_ps, "bench"));\n    o.oppBench = detail::parse_pokemon_list(jx::object_member(opp_ps, "bench"));\n\n    o.myHand = detail::parse_card_list(jx::object_member(my_ps, "hand"));\n    o.myDiscard = detail::parse_card_list(jx::object_member(my_ps, "discard"));\n    o.selectDeck = detail::parse_card_list(jx::object_member(*select, "deck"));\n    o.myPrizeCards = detail::parse_card_list(jx::object_member(my_ps, "prize"));\n    o.looking = detail::parse_card_list(jx::object_member(*current, "looking"));\n\n    o.myDeckCount = jx::to_int(jx::object_member(my_ps, "deckCount"), 0);\n    o.oppDeckCount = jx::to_int(jx::object_member(opp_ps, "deckCount"), 0);\n    o.oppHandCount = jx::to_int(jx::object_member(opp_ps, "handCount"), 0);\n\n    auto my_prize = jx::object_member(my_ps, "prize");\n    o.myPrizeCount = my_prize.has_value() ? static_cast<int>(jx::array_items(*my_prize).size()) : 0;\n    auto opp_prize = jx::object_member(opp_ps, "prize");\n    o.oppPrizeCount = opp_prize.has_value() ? static_cast<int>(jx::array_items(*opp_prize).size()) : 0;\n\n    o.myPoisoned = jx::to_bool(jx::object_member(my_ps, "poisoned"), false);\n    o.myBurned = jx::to_bool(jx::object_member(my_ps, "burned"), false);\n    o.myAsleep = jx::to_bool(jx::object_member(my_ps, "asleep"), false);\n    o.myParalyzed = jx::to_bool(jx::object_member(my_ps, "paralyzed"), false);\n    o.myConfused = jx::to_bool(jx::object_member(my_ps, "confused"), false);\n\n    // V20: opponent-side fields for the B1 vectorizer.\n    auto opp_discard = jx::object_member(opp_ps, "discard");\n    o.oppDiscardCount = opp_discard.has_value() ? static_cast<int>(jx::array_items(*opp_discard).size()) : 0;\n    o.oppPoisoned = jx::to_bool(jx::object_member(opp_ps, "poisoned"), false);\n    o.oppBurned = jx::to_bool(jx::object_member(opp_ps, "burned"), false);\n    o.oppAsleep = jx::to_bool(jx::object_member(opp_ps, "asleep"), false);\n    o.oppParalyzed = jx::to_bool(jx::object_member(opp_ps, "paralyzed"), false);\n    o.oppConfused = jx::to_bool(jx::object_member(opp_ps, "confused"), false);\n  }\n\n  auto options = jx::object_member(*select, "option");\n  if (options.has_value()) {\n    for (auto item : jx::array_items(*options)) {\n      Option op;\n      op.type = jx::to_int(jx::object_member(item, "type"), -1);\n      op.number = jx::to_int(jx::object_member(item, "number"), -1);\n      op.area = jx::to_int(jx::object_member(item, "area"), -1);\n      op.index = jx::to_int(jx::object_member(item, "index"), -1);\n      op.playerIndex = jx::to_int(jx::object_member(item, "playerIndex"), -1);\n      op.toolIndex = jx::to_int(jx::object_member(item, "toolIndex"), -1);\n      op.energyIndex = jx::to_int(jx::object_member(item, "energyIndex"), -1);\n      op.count = jx::to_int(jx::object_member(item, "count"), -1);\n      op.inPlayArea = jx::to_int(jx::object_member(item, "inPlayArea"), -1);\n      op.inPlayIndex = jx::to_int(jx::object_member(item, "inPlayIndex"), -1);\n      op.attackId = jx::to_int(jx::object_member(item, "attackId"), -1);\n      op.cardId = jx::to_int(jx::object_member(item, "cardId"), -1);\n      op.serial = jx::to_int(jx::object_member(item, "serial"), -1);\n      op.specialConditionType = jx::to_int(jx::object_member(item, "specialConditionType"), -1);\n      o.options.push_back(op);\n    }\n  }\n\n  return o;\n}\n\n}  // namespace v17\n')
write_source('v6_heuristic.hpp', '// Faithful C++ port of src/agents/dragapult_policy_v6.py\'s DragapultPolicy\n// (BALANCED weights) -- the exact scoring math this task requires (Objective\n// 2: "EXACT mathematical heuristic extracted from V6"). Ported statement-by-\n// statement against that file (read in full before writing this), preserving\n// its exact evaluation order, including the handful of places where a value\n// genuinely persists across calls (plan_a/plan_b/use_support -- only reset\n// inside the `context == MAIN` branch, exactly like the Python instance\n// attributes they mirror) and one apparent no-op branch in the original\n// (ENERGY_CARD/ENERGY scoring reads the POKEMON\'s cardType, not the energy\n// card\'s -- preserved verbatim rather than "fixed", per this task\'s fidelity\n// requirement).\n//\n// Used in two roles (see ../README.md): (1) the MCTS rollout/default policy\n// -- `choose()` drives every simulated decision after the root; (2)\n// `state_value()` (ported from src/agents/dragapult_policy_v11.py\'s\n// `post_action_state_value`, itself built on V6\'s own `pokemon_score`) is the\n// leaf/backup value MCTS actually optimizes.\n//\n// One V6Scorer instance persists for the whole process (the "live" decision\n// maker, exactly like Python\'s one long-lived DragapultPolicy instance).\n// MCTS copy-constructs a disposable scratch instance per simulated branch\n// (V6Scorer has no owning resources -- CardTable is a const reference to a\n// single process-lifetime table -- so the implicit copy constructor is\n// correct and cheap), mirroring V11\'s `copy.deepcopy(self)` +\n// `_rollout_mode` pattern for the exact same reason: a rollout must never\n// mutate the real decision-maker\'s plan_a_/plan_b_/use_support_ state.\n#pragma once\n\n#include <algorithm>\n#include <functional>\n#include <unordered_map>\n#include <vector>\n\n#include "card_data.hpp"\n#include "observation.hpp"\n\nnamespace v17 {\n\nstruct PolicyWeights {\n  double prize_value_multiplier = 1.0;\n  bool defensive_retreat_enabled = true;\n  double defensive_retreat_hp_fraction = 1.0;\n  double preservation_bias = 0.1;\n  double switch_risk_tolerance = 1.0;\n};\n\n// policy_weights.py\'s BALANCED profile -- the one V6/V11 actually play.\ninline PolicyWeights balanced_weights() {\n  return PolicyWeights{1.0, true, 1.0, 0.1, 1.0};\n}\n\nstruct AttackPlan {\n  int attack = -1;\n  std::vector<int> counter;\n};\n\n// --- cg.api enum values this scorer dispatches on (cg/api.py is ground truth) ---\nnamespace enums {\nconstexpr int AREA_DECK = 1, AREA_HAND = 2, AREA_DISCARD = 3, AREA_ACTIVE = 4, AREA_BENCH = 5, AREA_PRIZE = 6,\n              AREA_STADIUM = 7, AREA_LOOKING = 12;\nconstexpr int CT_POKEMON = 0, CT_TOOL = 2, CT_SUPPORTER = 3, CT_BASIC_ENERGY = 5, CT_SPECIAL_ENERGY = 6;\nconstexpr int OPT_NUMBER = 0, OPT_YES = 1, OPT_CARD = 3, OPT_ENERGY_CARD = 5, OPT_ENERGY = 6, OPT_PLAY = 7,\n              OPT_ATTACH = 8, OPT_EVOLVE = 9, OPT_ABILITY = 10, OPT_RETREAT = 12, OPT_ATTACK = 13;\nconstexpr int CTX_MAIN = 0, CTX_SETUP_ACTIVE_POKEMON = 1, CTX_SETUP_BENCH_POKEMON = 2, CTX_SWITCH = 3,\n              CTX_TO_ACTIVE = 4, CTX_TO_BENCH = 5, CTX_TO_HAND = 7, CTX_DISCARD = 8, CTX_DAMAGE_COUNTER = 13,\n              CTX_DAMAGE_COUNTER_ANY = 14, CTX_ATTACH_FROM = 21, CTX_IS_FIRST = 41;\n}  // namespace enums\n\nclass V6Scorer {\n public:\n  explicit V6Scorer(const CardTable& cards, PolicyWeights weights = balanced_weights())\n      : cards_(cards), weights_(weights) {}\n  V6Scorer(const V6Scorer&) = default;\n\n  // Decklist constants (dragapult_policy_v6.py module-level constants).\n  static constexpr int Dreepy = 119, Drakloak = 120, Dragapult_ex = 121, Fezandipiti_ex = 140, Latias_ex = 184,\n                        Budew = 235, Meowth_ex = 1071, Rare_Candy = 1079, Unfair_Stamp = 1080,\n                        Buddy_Buddy_Poffin = 1086, Night_Stretcher = 1097, Crushing_Hammer = 1120,\n                        Ultra_Ball = 1121, Poke_Pad = 1152, Lucky_Helmet = 1156, Boss_Orders = 1182,\n                        Crispin = 1198, Brock_Scouting = 1210, Lillie_Determination = 1227,\n                        Team_Rocket_Watchtower = 1256, Basic_Fire_Energy = 2, Basic_Psychic_Energy = 5;\n  static constexpr double UNNECESSARY = -10000000.0;\n  static constexpr int PHANTOM_DIVE_ATTACK_ID = 154;\n\n  // The full per-option score vector for `obs.options` -- direct C++\n  // translation of dragapult_policy_v6.py\'s `agent()` method body (minus the\n  // deck-declare/IS_FIRST short-circuits, both handled in Python before this\n  // is ever reached -- see main_v17.py).\n  std::vector<double> raw_scores(const Observation& obs);\n\n  // dragapult_policy_v6.py\'s select_top(): sorts by score descending\n  // (stable, matching Python\'s stable sort), returns the top maxCount\n  // indices, with the same TO_BENCH/SETUP_BENCH_POKEMON "allow declining\n  // below maxCount on an all-negative field" quirk preserved.\n  static std::vector<int> select_top(const Observation& obs, const std::vector<double>& scores);\n\n  // raw_scores() + select_top() -- V6\'s complete plain-greedy decision.\n  // This is both the MCTS rollout/default policy and the ultimate fallback\n  // if a root-level MCTS search cannot complete even one full evaluation.\n  std::vector<int> choose(const Observation& obs) {\n    std::vector<double> scores = raw_scores(obs);\n    return select_top(obs, scores);\n  }\n\n  // Ported unchanged from dragapult_policy_v11.py\'s `post_action_state_value`\n  // (itself built on V6\'s own `pokemon_score`) -- the MCTS leaf/backup value.\n  //\n  // `perspective_index` is the ROOT decision-maker\'s player index -- NOT\n  // necessarily `obs.myIndex`. Decisions alternate between players during a\n  // rollout (the engine\'s `yourIndex` tracks whoever is CURRENTLY acting,\n  // which is frequently the opponent by the time a rollout ends), so\n  // `obs.myActive`/`obs.myBench` may actually describe the OPPONENT\'s board\n  // by the final step. This function swaps sides internally whenever\n  // `perspective_index != obs.myIndex` so the returned value is always "how\n  // good is this outcome for the player who owns the real decision this\n  // whole search is for" -- getting this backwards would make MCTS\n  // systematically prefer moves that are good for the OPPONENT whenever the\n  // final rollout step happened to land on an opponent decision, which is a\n  // silent, high-impact scoring-sign bug, not a cosmetic one.\n  double state_value(const Observation& obs, int perspective_index) const;\n\n  double pokemon_score(const Pokemon& p, bool is_attack_damage) const;\n\n private:\n  const CardTable& cards_;\n  PolicyWeights weights_;\n\n  // Cross-call state -- ONLY mutated when context == MAIN, exactly mirroring\n  // the Python instance attributes of the same name (see file header).\n  AttackPlan plan_a_;\n  AttackPlan plan_b_;\n  bool can_switch_ = false;\n  bool can_attack_ = false;\n  bool can_main_attack_ = false;\n  int use_support_ = 0;\n\n  int prize_count(const Pokemon& p, bool is_attack_damage) const;\n  static bool no_damage_dex(int id) { return id == 158 || id == 207 || id == 330 || id == 345; }\n  static bool no_damage_counter_target(const Pokemon& p) {\n    if (p.id == 28 || p.id == 199 || p.id == 203 || p.id == 207 || p.id == 362 || p.id == 1136) return true;\n    for (int eid : p.energyCardIds) {\n      if (eid == 11 || eid == 20) return true;\n    }\n    return false;\n  }\n\n  void main_option_proc(const Observation& obs, int damage, bool bench_attacker);\n  bool wants_defensive_retreat(const Pokemon& my_active, const Pokemon& op_active, bool can_attack_now) const;\n  double board_value_side(const Pokemon& active, const std::vector<Pokemon>& bench) const;\n\n  // Returns nullptr for a face-down Pokemon, not just an absent one --\n  // matches Python\'s `get_card()`, which returns the raw slot contents and\n  // is `None` for BOTH "no active Pokemon at all" (empty list) AND "active\n  // Pokemon present but face-down" (a `None` array element, cg/api.py:\n  // "None if the card is facedown") -- V6 never distinguishes the two\n  // cases, always treating both as `is None`. Only `obs.oppActive`/\n  // `obs.oppBench` can ever be face-down (we always see our own board in\n  // full), but the check costs nothing to apply uniformly.\n  const Pokemon* get_pokemon(const Observation& obs, int area, int index, int player_index) const {\n    bool mine = (player_index == obs.myIndex);\n    const Pokemon* p = nullptr;\n    if (area == enums::AREA_ACTIVE) {\n      p = mine ? &obs.myActive : &obs.oppActive;\n    } else if (area == enums::AREA_BENCH) {\n      const std::vector<Pokemon>& bench = mine ? obs.myBench : obs.oppBench;\n      if (index >= 0 && static_cast<size_t>(index) < bench.size()) p = &bench[static_cast<size_t>(index)];\n    }\n    if (p && p->present && !p->faceDown) return p;\n    return nullptr;\n  }\n\n  // Matches Python\'s get_card() (src/agents/common.py) exactly: DECK/\n  // PRIZE/LOOKING are resolved directly from their own zone, independent of\n  // `player_index` (that field isn\'t consulted for them at all there --\n  // each is always OUR OWN visible zone), while HAND/DISCARD go through the\n  // owning player\'s zone. A PRIZE/LOOKING slot holding a face-down/\n  // unrevealed card is represented as id==0 (see v17_abi.h) -- treated as\n  // "not found", matching Python\'s `ps.prize[index]` being `None` there.\n  const Card* get_card_ref(const Observation& obs, int area, int index, int player_index) const {\n    if (area == enums::AREA_DECK) {\n      if (index >= 0 && static_cast<size_t>(index) < obs.selectDeck.size()) return &obs.selectDeck[static_cast<size_t>(index)];\n      return nullptr;\n    }\n    if (area == enums::AREA_PRIZE) {\n      if (index >= 0 && static_cast<size_t>(index) < obs.myPrizeCards.size()) {\n        const Card& c = obs.myPrizeCards[static_cast<size_t>(index)];\n        return c.id != 0 ? &c : nullptr;\n      }\n      return nullptr;\n    }\n    if (area == enums::AREA_LOOKING) {\n      if (index >= 0 && static_cast<size_t>(index) < obs.looking.size()) {\n        const Card& c = obs.looking[static_cast<size_t>(index)];\n        return c.id != 0 ? &c : nullptr;\n      }\n      return nullptr;\n    }\n    bool mine = (player_index == obs.myIndex);\n    if (!mine) return nullptr;  // V6 never CARD-references the opponent\'s hidden hand/discard by index\n    if (area == enums::AREA_HAND) {\n      if (index >= 0 && static_cast<size_t>(index) < obs.myHand.size()) return &obs.myHand[static_cast<size_t>(index)];\n    } else if (area == enums::AREA_DISCARD) {\n      if (index >= 0 && static_cast<size_t>(index) < obs.myDiscard.size()) return &obs.myDiscard[static_cast<size_t>(index)];\n    }\n    return nullptr;\n  }\n};\n\ninline double V6Scorer::pokemon_score(const Pokemon& p, bool is_attack_damage) const {\n  const CardData& data = cards_.card(p.id);\n  // Rebalanced 2026-08-14 (reward-hacking investigation into the\n  // MCTS:[PLAY] vs V6:[EVOLVE] pathology, ~11% win rate when diverged in the\n  // 80-game post-clip run): prize-count term was 1000x-scaled vs. a mere\n  // +130/+250 evolution-stage bonus, so a rollout-visible EX/prize-heavy\n  // basic Pokemon could dominate the score against evolving toward a\n  // stronger board, even when evolving was clearly better long-term. Only\n  // affects V17\'s OWN internal C++ scorer (this file) -- the actual V6\n  // opponent agent in tournament play is pure Python\n  // (dragapult_policy_v6.py, a separate, untouched implementation), so this\n  // does not change the baseline being played against, only V17\'s own\n  // candidate ranking/rollout evaluation.\n  double score = static_cast<double>(prize_count(p, is_attack_damage)) * 300.0 * weights_.prize_value_multiplier;\n  score += static_cast<double>(p.energies.size()) * 150.0;\n  score += static_cast<double>(p.toolIds.size()) * 100.0;\n  if (data.stage2) score += 1000;\n  else if (data.stage1) score += 600;\n  int id = p.id;\n  if (id == 173 || id == 174 || id == 190 || id == 1071) score -= 200;\n  if (id == 112 && !p.energies.empty()) score += 300;  // Munkidori\n  score += p.hp;\n  return score;\n}\n\ninline int V6Scorer::prize_count(const Pokemon& p, bool is_attack_damage) const {\n  const CardData& data = cards_.card(p.id);\n  int count = data.megaEx ? 3 : (data.ex ? 2 : 1);\n  if (is_attack_damage) {\n    for (int eid : p.energyCardIds) {\n      if (eid == 12) count -= 1;  // Legacy Energy\n    }\n    for (int tid : p.toolIds) {\n      if (tid == 1172 && data.name.find("Lillie") != std::string::npos) count -= 1;  // Lillie\'s Pearl\n    }\n  }\n  return std::max(0, count);\n}\n\ninline double V6Scorer::board_value_side(const Pokemon& active, const std::vector<Pokemon>& bench) const {\n  double total = 0.0;\n  if (active.present && !active.faceDown) total += pokemon_score(active, false);\n  for (const auto& p : bench) {\n    if (p.present && !p.faceDown) total += pokemon_score(p, false);\n  }\n  return total;\n}\n\ninline double V6Scorer::state_value(const Observation& obs, int perspective_index) const {\n  if (obs.result >= 0) {\n    if (obs.result == perspective_index) return 1000000.0;\n    if (obs.result == 1 - perspective_index) return -1000000.0;\n    return 0.0;\n  }\n  bool same_side = (perspective_index == obs.myIndex);\n  const Pokemon& me_active = same_side ? obs.myActive : obs.oppActive;\n  const std::vector<Pokemon>& me_bench = same_side ? obs.myBench : obs.oppBench;\n  const Pokemon& opp_active = same_side ? obs.oppActive : obs.myActive;\n  const std::vector<Pokemon>& opp_bench = same_side ? obs.oppBench : obs.myBench;\n  int me_prize = same_side ? obs.myPrizeCount : obs.oppPrizeCount;\n  int opp_prize = same_side ? obs.oppPrizeCount : obs.myPrizeCount;\n  double prize_term = static_cast<double>(opp_prize - me_prize) * 1000.0 * weights_.prize_value_multiplier;\n  return board_value_side(me_active, me_bench) - board_value_side(opp_active, opp_bench) + prize_term;\n}\n\ninline bool V6Scorer::wants_defensive_retreat(const Pokemon& my_active, const Pokemon& op_active, bool can_attack_now) const {\n  if (!weights_.defensive_retreat_enabled) return false;\n  if (can_attack_now) return false;\n  if (!my_active.present || !op_active.present || op_active.faceDown) return false;\n  if (!cards_.has_card(op_active.id)) return false;\n  const CardData& op_card = cards_.card(op_active.id);\n  int op_energy_count = static_cast<int>(op_active.energies.size());\n  double threshold = my_active.hp * weights_.defensive_retreat_hp_fraction;\n  for (int aid : op_card.attacks) {\n    const AttackData& atk = cards_.attack(aid);\n    if (atk.damage <= 0) continue;  // also naturally skips an unknown attack id (default damage=0)\n    if (op_energy_count >= static_cast<int>(atk.energies.size()) && atk.damage >= threshold) return true;\n  }\n  return false;\n}\n\n// Verbatim (list-operation-for-list-operation) port of main_option_proc\'s\n// subset-sum DFS over "which bench Pokemon to also place Phantom Dive\'s 6\n// damage counters on" -- see V6 FIX #1/#2 comments in the .cpp/py source this\n// mirrors. Deliberately NOT rewritten into a cleaner recursive form: the\n// iterative stack-based traversal order affects nothing observable here\n// (every valid subset is still found), but a literal port is far easier to\n// audit against the original than a reimplementation would be.\ninline void V6Scorer::main_option_proc(const Observation& obs, int damage, bool bench_attacker) {\n  can_switch_ = false;\n  can_attack_ = false;\n  can_main_attack_ = false;\n  for (const Option& o : obs.options) {\n    if (o.type == enums::OPT_RETREAT) can_switch_ = true;\n    else if (o.type == enums::OPT_ATTACK) {\n      can_attack_ = true;\n      if (o.attackId == PHANTOM_DIVE_ATTACK_ID) can_main_attack_ = true;\n    }\n  }\n\n  plan_a_.attack = -1;\n  plan_a_.counter.clear();\n  plan_b_.attack = -1;\n  plan_b_.counter.clear();\n  if (!can_main_attack_ && !(bench_attacker && can_switch_)) return;\n  // Defensive: Python\'s un-ported equivalent (`op_state.active[0]`) would\n  // crash here if the opponent\'s Active is absent or face-down; there is\n  // nothing to plan against either way, so bail out cleanly instead (bench\n  // entries are never face-down -- cg/api.py types `bench: list[Pokemon]`,\n  // not `list[Pokemon|None]` -- only the single Active slot can be).\n  if (!obs.oppActive.present || obs.oppActive.faceDown) return;\n\n  std::vector<Pokemon> cards;\n  cards.push_back(obs.oppActive);\n  for (const auto& p : obs.oppBench) cards.push_back(p);\n\n  std::vector<std::vector<int>> counter_indices;\n  std::vector<int> ci = {0};\n  int remain_damage = 60;\n  while (!ci.empty()) {\n    int index = ci.back();\n    int hp = cards[static_cast<size_t>(index)].hp;\n    if (remain_damage >= hp) {\n      counter_indices.push_back(ci);\n      if (index < static_cast<int>(cards.size()) - 1) {\n        remain_damage -= hp;\n        ci.push_back(index + 1);\n        continue;\n      }\n    }\n    if (index == static_cast<int>(cards.size()) - 1) {\n      ci.pop_back();\n      if (!ci.empty()) remain_damage += cards[static_cast<size_t>(ci.back())].hp;\n    }\n    if (!ci.empty()) ci.back() += 1;\n  }\n  counter_indices.push_back({});\n\n  int remain_prize = obs.myPrizeCount;\n  double plan_score = 0;\n  for (int i = 0; i < static_cast<int>(cards.size()); ++i) {\n    const Pokemon& pokemon = cards[static_cast<size_t>(i)];\n    int base_prize_count = 0;\n    double base_score = pokemon_score(pokemon, true);\n    int active_damage;\n    if (i == 0 && can_main_attack_) {\n      // V6 FIX #2: Phantom Dive never damages the opponent\'s Active.\n      active_damage = 0;\n    } else {\n      active_damage = no_damage_dex(pokemon.id) ? 0 : damage;\n    }\n    if (pokemon.hp <= active_damage) {\n      base_prize_count += prize_count(pokemon, true);\n    } else {\n      base_score *= static_cast<double>(active_damage) / static_cast<double>(pokemon.hp);\n    }\n    std::vector<int> best_indices;\n    double max_score = base_score;\n    if (remain_prize <= base_prize_count) {\n      max_score = 50000;\n    } else {\n      for (const auto& indices : counter_indices) {\n        if (std::find(indices.begin(), indices.end(), i) != indices.end()) continue;\n        int prize = base_prize_count;\n        double score = base_score;\n        for (int index : indices) {\n          prize += prize_count(cards[static_cast<size_t>(index)], false);\n          score += pokemon_score(cards[static_cast<size_t>(index)], false);\n        }\n        if (remain_prize <= prize) {\n          score = 50000;\n        } else if (prize >= 2) {\n          if (remain_prize <= 4) score -= 1200;\n        } else if (prize == 1) {\n          score -= 300;\n        } else {\n          score += 1200;\n        }\n        if (max_score < score) {\n          max_score = score;\n          best_indices = indices;\n        }\n      }\n    }\n    if (plan_score < max_score) {\n      plan_score = max_score;\n      plan_a_.attack = i;\n      plan_a_.counter = best_indices;\n    }\n    if (i == 0) {\n      plan_b_.attack = plan_a_.attack;\n      plan_b_.counter = plan_a_.counter;\n    }\n  }\n}\n\n}  // namespace v17\n')
write_source('v6_heuristic_scores.hpp', '// Out-of-line definitions of V6Scorer::raw_scores / select_top -- split from\n// v6_heuristic.hpp purely to keep individual files reviewable; logically\n// part of the same class. #include v6_heuristic.hpp before this file.\n//\n// This is the direct translation of dragapult_policy_v6.py\'s `agent()`\n// method body: the field/hand/discard counting preamble, the `attach_score`/\n// `hand_score` nested closures (here: `std::function` locals capturing by\n// reference, exactly mirroring Python\'s closures over the same mutable\n// locals), and the per-option `for o in select.option: ...` dispatch.\n// Statement order is preserved deliberately (see v6_heuristic.hpp\'s header\n// comment) because several values are genuinely order-dependent\n// (hand_counts/support_count are mutated mid-loop and read by later\n// iterations, exactly as in the Python original).\n#pragma once\n\n#include "v6_heuristic.hpp"\n\nnamespace v17 {\n\ninline std::vector<double> V6Scorer::raw_scores(const Observation& obs) {\n  using namespace enums;\n\n  // --- field_counts / bench_attacker / evolve-eligibility preamble ---\n  // (dragapult_policy_v6.py: the two `for card in my_state.active/bench`\n  // loops, unconditional every call.)\n  std::unordered_map<int, int> field_counts;\n  int active_id = 0;\n  bool bench_attacker = false;\n  bool can_evolve_dreepy = false;\n  int evolve_dreepy_count = 0;\n  bool can_evolve_drakloak = false;\n  const int damage = 200;\n\n  if (obs.myActive.present) {\n    active_id = obs.myActive.id;\n    field_counts[obs.myActive.id] += 1;\n    if (!obs.myActive.appearThisTurn) {\n      if (obs.myActive.id == Dreepy) {\n        can_evolve_dreepy = true;\n        evolve_dreepy_count += 1;\n      } else if (obs.myActive.id == Drakloak) {\n        can_evolve_drakloak = true;\n      }\n    }\n  }\n  for (const auto& card : obs.myBench) {\n    if (!card.present) continue;\n    field_counts[card.id] += 1;\n    if (!card.appearThisTurn) {\n      if (card.id == Dreepy) {\n        can_evolve_dreepy = true;\n        evolve_dreepy_count += 1;\n      } else if (card.id == Drakloak) {\n        can_evolve_drakloak = true;\n      }\n    }\n    if (card.id == Dragapult_ex && static_cast<int>(card.energies.size()) >= 2) bench_attacker = true;\n  }\n\n  int main_pokemon_count = field_counts[Dreepy] + field_counts[Drakloak] + field_counts[Dragapult_ex];\n  bool no_more_dex = field_counts[Dragapult_ex] * 2 >= obs.oppPrizeCount;\n  int stadium_id = obs.stadiumCardId;\n  int support_count = 0;\n\n  std::unordered_map<int, int> discard_counts;\n  for (const auto& c : obs.myDiscard) discard_counts[c.id] += 1;\n\n  std::unordered_map<int, int> deck_counts_map;\n  for (const auto& kv : obs.deckCounts) deck_counts_map[kv.first] = kv.second;\n  auto deck_count = [&](int id) -> int {\n    auto it = deck_counts_map.find(id);\n    return it == deck_counts_map.end() ? 0 : it->second;\n  };\n\n  const bool pre_ko = obs.preKo;\n  const bool no_item = obs.noItem;\n  const int prize_diff = obs.myPrizeCount - obs.oppPrizeCount;\n\n  // hand_counts is mutated DURING both the hand_scores pass below and the\n  // main options loop (TO_BENCH/TO_HAND/DISCARD contexts) -- captured by\n  // reference throughout, exactly matching the Python closures\' behavior.\n  std::unordered_map<int, int> hand_counts;\n\n  // --- attach_score (dragapult_policy_v6.py\'s nested `attach_score`) ---\n  auto attach_score = [&](int attach_id, const Pokemon& pokemon, bool active) -> double {\n    int energy_count = static_cast<int>(pokemon.energies.size());\n    if (cards_.card(attach_id).cardType == CT_TOOL) {\n      double score = 60000;\n      if (active) score += 1000;\n      return score;\n    }\n    if (pokemon.id == Budew) return -1;\n    if (pokemon.id == Meowth_ex || pokemon.id == Fezandipiti_ex || pokemon.id == Latias_ex) {\n      if (active && !can_switch_ && !obs.myAsleep && !obs.myParalyzed) {\n        if (bench_attacker || field_counts[Budew] >= 1) return 22000;\n        return 18000;\n      }\n      return -1;\n    }\n    if (active && can_main_attack_) return -1;\n    double score = 20000;\n    if (energy_count >= 2) {\n      if (active && !can_switch_ && !obs.myAsleep && !obs.myParalyzed) {\n        score += 200;\n      } else {\n        return -1;\n      }\n    } else if (energy_count == 1) {\n      if (!pokemon.energyCardIds.empty() && attach_id == pokemon.energyCardIds[0]) return -1;\n      if (pokemon.id == Dragapult_ex) score += 250;\n      else if (pokemon.id == Dreepy) score -= 150;\n      else score -= 200;\n      if (active) score += 200;\n    } else {\n      if (active) {\n        if (bench_attacker) score += 400;\n      } else {\n        if (pokemon.id == Dragapult_ex) score += 150;\n        else if (pokemon.id == Dreepy) score += 100;\n        else score += 50;\n        if (bench_attacker) score -= 200;\n      }\n    }\n    if (no_more_dex && (pokemon.id == Dreepy || pokemon.id == Drakloak)) score -= 500;\n    return score;\n  };\n\n  // --- hand_score (dragapult_policy_v6.py\'s nested `hand_score`, recursive\n  // via Night_Stretcher) ---\n  std::function<double(int, bool)> hand_score = [&](int id, bool ignore_count) -> double {\n    double score = 0;\n    if (id == Dreepy) {\n      score = (main_pokemon_count >= 3) ? 1000 : 18000;\n    } else if (id == Drakloak) {\n      score = can_evolve_dreepy ? 20000 : 3000;\n    } else if (id == Dragapult_ex) {\n      if (no_more_dex) {\n        score = UNNECESSARY;\n      } else if (can_evolve_dreepy && hand_counts[Rare_Candy] >= 1 && !no_item) {\n        score = 40000;\n      } else if (can_evolve_drakloak) {\n        if (field_counts[Dragapult_ex] == 0) score = 30000;\n        else if (field_counts[Dragapult_ex] == 1) score = 10000;\n        else score = 50;\n      } else {\n        score = (field_counts[Dragapult_ex] >= 2) ? 50 : 2000;\n      }\n    } else if (id == Fezandipiti_ex) {\n      if (pre_ko) score = 50000;\n      else if (prize_diff <= -2) score = 5;\n      else if (obs.oppPrizeCount == 1) score = UNNECESSARY;\n    } else if (id == Latias_ex) {\n      if (active_id == Fezandipiti_ex || active_id == Meowth_ex || active_id == Dreepy) {\n        score = (field_counts[Drakloak] + field_counts[Dragapult_ex] == 0) ? 28000 : 15000;\n      } else {\n        score = 10;\n      }\n    } else if (id == Budew) {\n      if (field_counts[Budew] + field_counts[Drakloak] + field_counts[Dragapult_ex] >= 1) score = UNNECESSARY;\n      else if (obs.turn >= 2) score = 30000;\n    } else if (id == Meowth_ex) {\n      if (support_count > hand_counts[Boss_Orders] || stadium_id == Team_Rocket_Watchtower) score = 5;\n      else if (obs.supporterPlayed) score = 40;\n      else score = 35000;\n    } else if (id == Rare_Candy) {\n      if (no_more_dex) score = UNNECESSARY;\n      else if (can_evolve_dreepy && hand_counts[Dragapult_ex] >= 1) score = 40000;\n    } else if (id == Unfair_Stamp) {\n      if (pre_ko) score = 80000;\n      else if (obs.oppPrizeCount == 1) score = UNNECESSARY;\n      else score = 80;\n    } else if (id == Buddy_Buddy_Poffin) {\n      int count = deck_count(Dreepy);\n      if (count == 0) {\n        score = UNNECESSARY;\n      } else {\n        if (obs.turn <= 2 && field_counts[Budew] == 0 && deck_count(Budew) >= 1) count += 1;\n        if (count >= 2) score = 35000;\n      }\n    } else if (id == Night_Stretcher) {\n      for (const auto& kv : discard_counts) {\n        if (kv.second >= 1) {\n          int card_type = cards_.card(kv.first).cardType;\n          if (card_type == CT_POKEMON || card_type == CT_BASIC_ENERGY) {\n            score = std::max(score, hand_score(kv.first, ignore_count));\n          }\n        }\n      }\n    } else if (id == Crushing_Hammer) {\n      score = 20;\n    } else if (id == Ultra_Ball) {\n      score = (main_pokemon_count <= 2 || field_counts[Dreepy] >= 1) ? 70 : 5;\n    } else if (id == Poke_Pad) {\n      score = std::max(hand_score(Dreepy, ignore_count), hand_score(Drakloak, ignore_count));\n    } else if (id == Lucky_Helmet) {\n      score = 15;\n    } else if (id == Boss_Orders) {\n      if (plan_a_.attack > 0) score = 60000;\n    } else if (id == Crispin) {\n      if (!ignore_count || support_count == 0) {\n        if (deck_count(Basic_Fire_Energy) == 0 || deck_count(Basic_Psychic_Energy) == 0) score = 10;\n        if (!can_main_attack_ && !bench_attacker && field_counts[Dragapult_ex] >= 1) score = 55000;\n        else score = 25000;\n      }\n    } else if (id == Brock_Scouting) {\n      if (!ignore_count || support_count == 0) {\n        if (obs.turn == 2 && field_counts[Budew] + field_counts[Latias_ex] == 0) score = 50000;\n        else score = 30000;\n      }\n    } else if (id == Lillie_Determination) {\n      if (!ignore_count || support_count == 0) score = 45000;\n    } else if (id == Team_Rocket_Watchtower) {\n      if (stadium_id != 0 && stadium_id != Team_Rocket_Watchtower) score = 4000;\n    } else if (id == Basic_Fire_Energy || id == Basic_Psychic_Energy) {\n      if (can_main_attack_ && (obs.oppPrizeCount <= 2 || (bench_attacker && obs.oppPrizeCount <= 4))) {\n        score = UNNECESSARY;\n      } else {\n        double max_score = -10000;\n        if (obs.myActive.present) max_score = std::max(max_score, attach_score(id, obs.myActive, true));\n        for (const auto& p : obs.myBench) {\n          if (p.present) max_score = std::max(max_score, attach_score(id, p, false));\n        }\n        score = max_score - 5000;\n        if (can_main_attack_ || bench_attacker) score /= 10;\n      }\n    }\n\n    if (!ignore_count && hand_counts[id] > 0) {\n      if (id == Drakloak && hand_counts[id] < evolve_dreepy_count) score -= 10;\n      else if (id == Dreepy) score -= 100;\n      else score -= 100000;\n    }\n    return score;\n  };\n\n  // --- MAIN-context preamble: main_option_proc + use_support determination.\n  // ONLY runs when context == MAIN -- everything it sets (plan_a_/plan_b_/\n  // can_switch_/can_attack_/can_main_attack_/use_support_) otherwise carries\n  // its value forward from the previous MAIN-context call, exactly like the\n  // Python instance attributes it mirrors (see v6_heuristic.hpp header). ---\n  if (obs.context == CTX_MAIN) {\n    main_option_proc(obs, damage, bench_attacker);\n\n    use_support_ = 0;\n    if (!obs.supporterPlayed) {\n      double support_score = 0;\n      for (const Option& o : obs.options) {\n        if (o.type == OPT_PLAY) {\n          const Card* c = get_card_ref(obs, AREA_HAND, o.index, obs.myIndex);\n          if (c && cards_.card(c->id).cardType == CT_SUPPORTER) {\n            double score = hand_score(c->id, true);\n            if (support_score < score) {\n              support_score = score;\n              use_support_ = c->id;\n            }\n          }\n        }\n      }\n    }\n  }\n\n  // --- per-hand-card scores (also grows hand_counts/support_count, order-\n  // dependent: a duplicate card\'s hand_score sees prior copies already\n  // counted but not itself -- see file header). ---\n  std::vector<double> hand_scores;\n  int negative_hand_count = 0;\n  for (const auto& card : obs.myHand) {\n    double score = hand_score(card.id, false);\n    hand_scores.push_back(score);\n    if (score < 0) negative_hand_count += 1;\n    hand_counts[card.id] += 1;\n    if (cards_.card(card.id).cardType == CT_SUPPORTER && card.id != Boss_Orders) support_count += 1;\n  }\n\n  bool no_draw = obs.myDeckCount <= 8;\n  bool do_switch = !can_main_attack_ && (bench_attacker || (active_id != Budew && field_counts[Budew] >= 1 && obs.turn >= 2));\n  if (!do_switch) {\n    do_switch = wants_defensive_retreat(obs.myActive, obs.oppActive, can_attack_);\n  }\n  int effect_card_id = obs.effectCardId;\n  int context_card_id = obs.contextCardId;\n\n  std::vector<double> scores;\n  scores.reserve(obs.options.size());\n\n  for (const Option& o : obs.options) {\n    double score = 0;\n\n    if (o.type == OPT_NUMBER) {\n      score = o.number;\n    } else if (o.type == OPT_YES) {\n      score = (obs.context == CTX_IS_FIRST) ? -1 : 1;\n    } else if (o.type == OPT_CARD) {\n      const Pokemon* p = nullptr;\n      const Card* c = nullptr;\n      int card_id = -1;\n      bool found = false;\n      int energy_count = 0, hp = 0;\n      if (o.area == AREA_ACTIVE || o.area == AREA_BENCH) {\n        p = get_pokemon(obs, o.area, o.index, o.playerIndex);\n        if (p && p->present) {\n          found = true;\n          card_id = p->id;\n          energy_count = static_cast<int>(p->energies.size());\n          hp = p->hp;\n        }\n      } else {\n        c = get_card_ref(obs, o.area, o.index, o.playerIndex);\n        if (c) {\n          found = true;\n          card_id = c->id;\n        }\n      }\n\n      if (found) {\n        if (obs.context == CTX_SWITCH || obs.context == CTX_TO_ACTIVE || obs.context == CTX_SETUP_ACTIVE_POKEMON) {\n          if (o.playerIndex == obs.myIndex) {\n            if (card_id == Dreepy) score += 10000;\n            else if (card_id == Drakloak) score += (energy_count >= 1) ? 20000 : -10000;\n            else if (card_id == Dragapult_ex) score += 50000;\n            else if (card_id == Budew) {\n              if (obs.context != CTX_SWITCH) score += 100000;\n              else if (!bench_attacker) score += 30000;\n            } else if (card_id == Fezandipiti_ex) {\n              score -= 1000.0 / weights_.switch_risk_tolerance;\n            } else if (card_id == Meowth_ex) {\n              score -= 2000.0 / weights_.switch_risk_tolerance;\n            }\n          } else {\n            if (plan_a_.attack == o.index + 1) score += 100000;\n          }\n          score += energy_count * 1000;\n          score += hp * (1 + weights_.preservation_bias);\n        } else if (obs.context == CTX_SETUP_BENCH_POKEMON) {\n          if (obs.myIndex == obs.firstPlayer || card_id != Dreepy) score = -1;\n        } else if (obs.context == CTX_TO_BENCH || obs.context == CTX_TO_HAND) {\n          score = hand_score(card_id, false);\n          hand_counts[card_id] += 1;\n          if (effect_card_id == Crispin) score = 100000 - hand_score(card_id, true);\n        } else if (obs.context == CTX_DISCARD) {\n          hand_counts[card_id] -= 1;\n          if (cards_.card(card_id).cardType == CT_SUPPORTER) support_count -= 1;\n          score = -hand_score(card_id, false);\n        } else if (obs.context == CTX_DAMAGE_COUNTER || obs.context == CTX_DAMAGE_COUNTER_ANY) {\n          if (hp > 0 && p != nullptr) {\n            score = 100000 - 10 * hp + pokemon_score(*p, false);\n            if (obs.context == CTX_DAMAGE_COUNTER) {\n              if (hp >= 210 && hp <= 230) {\n                score += 20000 + hp * 20;\n                if (o.area == AREA_ACTIVE) score += 10000;\n              } else if (hp >= 40 && hp <= 90) {\n                score += 10000 + hp * 20;\n              } else if (hp <= 30) {\n                score += -10000 + hp * 20;\n              }\n              if (card_id == 133 || card_id == 351) score += 30000;\n            } else {\n              int index = o.index + 1;\n              if (std::find(plan_b_.counter.begin(), plan_b_.counter.end(), index) != plan_b_.counter.end()) {\n                score += 100000;\n              } else {\n                int remain_damage = obs.remainDamageCounter * 10;\n                if (hp >= 210 && hp <= 200 + remain_damage) score += 30000;\n                else if (hp >= 20 && hp <= 60 + remain_damage) score += 10000;\n                else if (hp == 10) score += 40000;  // V6 FIX #1\n              }\n              if (no_damage_counter_target(*p)) score = -1;\n            }\n          }\n        } else if (obs.context == CTX_ATTACH_FROM) {\n          if (p != nullptr) {\n            score = attach_score(context_card_id, *p, o.area == AREA_ACTIVE);\n            if (card_id == Dragapult_ex) score += 200;\n          }\n        }\n      }\n    } else if (o.type == OPT_ENERGY_CARD || o.type == OPT_ENERGY) {\n      if (o.playerIndex != obs.myIndex) {\n        score = (o.area == AREA_BENCH) ? 20 : 10;\n        // Faithful port of an apparent no-op in the original: this reads the\n        // POKEMON at (area,index) rather than the energy card itself, so the\n        // cardType check below is never CT_SPECIAL_ENERGY in practice.\n        // Preserved as-is (see file header) rather than "corrected".\n        const Pokemon* p = get_pokemon(obs, o.area, o.index, o.playerIndex);\n        if (p && p->present && cards_.card(p->id).cardType == CT_SPECIAL_ENERGY) score += 1;\n      }\n    } else if (o.type == OPT_PLAY) {\n      const Card* hand_card = get_card_ref(obs, AREA_HAND, o.index, obs.myIndex);\n      int card_id = hand_card ? hand_card->id : -1;\n      double card_score = (o.index >= 0 && static_cast<size_t>(o.index) < hand_scores.size()) ? hand_scores[static_cast<size_t>(o.index)] : 0.0;\n      if (card_id == Dreepy) {\n        score = 51000;\n      } else if (card_id == Fezandipiti_ex) {\n        score = (card_score > 0) ? 53000 : -1;\n      } else if (card_id == Latias_ex) {\n        score = (active_id != Drakloak && active_id != Dragapult_ex) ? 51000 : -1;\n      } else if (card_id == Budew) {\n        score = (field_counts[Budew] == 0 && field_counts[Dragapult_ex] == 0) ? 52000 : -1;\n      } else if (card_id == Meowth_ex) {\n        if (obs.supporterPlayed || stadium_id == Team_Rocket_Watchtower) score = -1;\n        else if (support_count == 0) score = 50000;\n        else if (support_count == hand_counts[Boss_Orders] && plan_a_.attack > 0) score = 50000;\n        else score = -1;\n      } else if (card_id == Rare_Candy) {\n        score = no_more_dex ? -1 : 75000;\n      } else if (card_id == Unfair_Stamp) {\n        score = 15000;\n      } else if (card_id == Night_Stretcher) {\n        score = (card_score >= 18000) ? 42000 : -1;\n      } else if (card_id == Crushing_Hammer) {\n        score = 40000;\n      } else if (card_id == Boss_Orders) {\n        score = (card_id == use_support_) ? 35000 : -1;\n      } else if (card_id == Lillie_Determination) {\n        score = (card_id == use_support_) ? 14000 : -1;\n      } else if (card_id == Team_Rocket_Watchtower) {\n        score = (stadium_id > 0 || obs.turn == 1) ? 80000 : -1;\n      } else if (no_draw) {\n        score = -1;\n      } else if (card_id == Buddy_Buddy_Poffin) {\n        score = (deck_count(Dreepy) > 0) ? 46000 : -1;\n      } else if (card_id == Ultra_Ball) {\n        score = (negative_hand_count >= 2) ? 44000 : -1;\n      } else if (card_id == Poke_Pad) {\n        score = (deck_count(Dreepy) + deck_count(Drakloak) > 0) ? 45000 : -1;\n      } else if (card_id == Crispin || card_id == Brock_Scouting) {\n        score = (card_id == use_support_) ? 35000 : -1;\n      }\n    } else if (o.type == OPT_ATTACH) {\n      const Card* hand_card = get_card_ref(obs, o.area, o.index, obs.myIndex);\n      const Pokemon* target = get_pokemon(obs, o.inPlayArea, o.inPlayIndex, obs.myIndex);\n      if (hand_card && target && target->present) {\n        score = attach_score(hand_card->id, *target, o.inPlayArea == AREA_ACTIVE);\n      }\n    } else if (o.type == OPT_EVOLVE) {\n      const Pokemon* target = get_pokemon(obs, o.inPlayArea, o.inPlayIndex, obs.myIndex);\n      if (target && target->present) {\n        score += static_cast<double>(target->energies.size());\n        if (target->id == Dreepy) {\n          score += 30000;\n        } else if (field_counts[Dragapult_ex] >= 2 || (field_counts[Dragapult_ex] == 1 && obs.oppPrizeCount <= 2)) {\n          score = -1;\n        } else {\n          score += 70000;\n        }\n      }\n    } else if (o.type == OPT_ABILITY) {\n      int card_id = -1;\n      const Card* c = get_card_ref(obs, o.area, o.index, obs.myIndex);\n      if (c) {\n        card_id = c->id;\n      } else {\n        const Pokemon* p = get_pokemon(obs, o.area, o.index, obs.myIndex);\n        if (p && p->present) card_id = p->id;\n        else if (o.area == AREA_STADIUM) card_id = obs.stadiumCardId;\n      }\n      if (no_draw) score = -1;\n      else if (card_id == 1267) score = 1;  // Lumiose City\n      else score = 40000;\n    } else if (o.type == OPT_RETREAT) {\n      score = do_switch ? 10000 : -1;\n    } else if (o.type == OPT_ATTACK) {\n      score = o.attackId;\n    }\n\n    scores.push_back(score);\n  }\n\n  return scores;\n}\n\ninline std::vector<int> V6Scorer::select_top(const Observation& obs, const std::vector<double>& scores) {\n  using namespace enums;\n  if (scores.empty()) return {};\n  std::vector<int> ranked(scores.size());\n  for (size_t i = 0; i < scores.size(); ++i) ranked[i] = static_cast<int>(i);\n  std::stable_sort(ranked.begin(), ranked.end(),\n                    [&](int a, int b) { return scores[static_cast<size_t>(a)] > scores[static_cast<size_t>(b)]; });\n\n  std::vector<int> output;\n  int max_count = std::min(obs.maxCount, static_cast<int>(ranked.size()));\n  for (int i = 0; i < max_count; ++i) {\n    int idx = ranked[static_cast<size_t>(i)];\n    double score = scores[static_cast<size_t>(idx)];\n    if (score >= 0 || obs.minCount > i || (obs.context != CTX_TO_BENCH && obs.context != CTX_SETUP_BENCH_POKEMON)) {\n      output.push_back(idx);\n    }\n  }\n  return output;\n}\n\n}  // namespace v17\n')
write_source('mcts.hpp', '// MCTS over the current real decision\'s legal options -- Selection\n// (UCB1) / Expansion (one search_step per visit) / Simulation (native\n// V6-greedy rollout) / Backpropagation (mean-value update per candidate),\n// entirely inside C++ against the native engine (see ../README.md\'s\n// call-chain diagram -- Python is not involved anywhere in this file).\n//\n// Scope, deliberately: the tree has exactly one branching level -- the K\n// legal options at the CURRENT decision (mirrors dragapult_policy_v11.py\'s\n// own gating: only `context == MAIN && maxCount == 1 && len(options) >= 2`\n// gets this treatment; every other decision, including every decision\n// *inside* a rollout, uses V6Scorer::choose() directly).\n//\n// 2026-08-14 stabilization pass (divergence investigation: whenever MCTS\n// overrode V6\'s greedy pick it won only 8-12% of those games -- see\n// MCTS:[END]/[EVOLVE]/[ABILITY] divergence buckets):\n//   1. VALUE NORMALIZATION: every rollout value is squashed through\n//      tanh(v / kValueSquashScale) into [-1, 1] BEFORE entering a\n//      candidate\'s running mean. UCB1\'s exploration math assumes bounded\n//      rewards; the previous clip-to-+-5000 left means on an arbitrary\n//      unbounded heuristic scale where the exploration constant had to be\n//      hand-rescaled 300x (the old kUcb1ExplorationScale) to matter at all,\n//      and a single outlier sample could still swing an arm\'s mean past any\n//      exploration correction.\n//   2. RE-DETERMINIZATION: search_begin is re-issued with a FRESH randomized\n//      guess of the opponent\'s hidden zones several times per search, and\n//      candidate statistics are averaged across all determinizations.\n//      Previously ONE search_begin filled the opponent\'s entire deck, hand,\n//      and prizes with Basic Fire Energy -- every rollout then played\n//      against an opponent who literally could not evolve, play a trainer,\n//      or threaten anything, so lines like "end the turn, nothing bad\n//      happens" scored beautifully in the tree and lost on the real board.\n//      The guess pool is our own DECK constant minus the opponent\'s visible\n//      board (mirror-match assumption -- the archetype this scorer is\n//      specialized for anyway), which is far closer to reality than 60\n//      energies and, critically, DIFFERENT each determinization, so a line\n//      must be good across several sampled worlds to keep a high mean.\n//   3. GREEDY-OVERRIDE MARGIN: MCTS\'s best-mean candidate replaces V6\'s own\n//      greedy pick only when its mean beats the greedy pick\'s mean by a\n//      clear margin on the squashed scale. At 8-12% observed override win\n//      rates, an override needs real evidence, not sampling noise.\n//   4. ROLLOUT TRUNCATION: rollouts stop at max_rollout_steps = 24 decisions\n//      (~2 simulated turns) instead of 60, then score with state_value() --\n//      horizon optimism compounds with rollout depth, and shorter rollouts\n//      buy more samples per determinization inside the same budget.\n#pragma once\n\n#include <algorithm>\n#include <chrono>\n#include <cmath>\n#include <random>\n#include <string>\n#include <vector>\n\n#include "card_data.hpp"\n#include "cg_engine.hpp"\n#include "deck_tracking.hpp"\n#include "generic_opponent.hpp"\n#include "observation.hpp"\n#include "pwin_trees.hpp"\n#include "v6_heuristic.hpp"\n#include "v6_heuristic_scores.hpp"\n#include "vectorizer.hpp"\n\nnamespace v17 {\n\n// tanh squash scale (stabilization note #1): typical non-terminal\n// state_value() magnitudes are a few hundred to a few thousand\n// (pokemon_score/prize_term), so /2500 keeps ordinary positional\n// differences on tanh\'s responsive slope, while a genuine terminal reward\n// (+-1,000,000, from the unmodified state_value() port) saturates to\n// exactly +-1 -- still decisive per-sample, but no longer able to swing a\n// mean by orders of magnitude off a single rollout. state_value() itself\n// stays an unmodified, faithful port (this project\'s standing rule: scope\n// the fix at the consumer, don\'t edit shared formula code).\nconstexpr double kValueSquashScale = 2500.0;\n\nstruct McTsConfig {\n  double time_budget_ms = 300.0;     // wall-clock budget for one v17_choose_action call\n  double safety_buffer_ms = 100.0;   // reserved, never spent on simulation (Objective 2\'s "100ms safety buffer")\n  int max_rollout_steps = 24;        // decisions per rollout (~2 simulated turns) -- stabilization note #4\n  int num_determinizations = 6;      // fresh opponent-hidden-zone samples per search -- stabilization note #2\n  double ucb1_c = 1.25;              // exploration constant (B2/PUCT: multiplies the prior term)\n  double greedy_override_margin = 0.20;  // note #3: minimum mean advantage (squashed scale) required to override V6\'s greedy pick\n                                          // (0.10 -> 0.20 after the 2026-08-14 120-game run: overrides averaged ~44% WR vs the\n                                          // 47.5% baseline -- low-confidence overrides still net-negative, confident ones\n                                          // (ATTACK-vs-PLAY 56.5%, ATTACK-vs-ABILITY 62.1%) worth keeping)\n  // V20 / Block B additions:\n  bool use_pwin_eval = true;   // B1: leaf/rollout value = learned P(win) mapped to [-1,1] (replaces tanh(state_value))\n  bool use_puct = true;        // B2: PUCT selection with V6-greedy-score softmax priors (replaces plain UCB1)\n  bool use_det_voting = true;  // B3: candidate chosen by per-determinization vote majority, mean as tie-break\n  double puct_prior_temperature = 20000.0;  // softmax temperature over raw V6 scores (typical real-option scores span 1e4-1e5)\n};\n\nstruct ChildStat {\n  int option_index = -1;\n  int visits = 0;\n  double total_value = 0.0;\n  double mean() const { return visits > 0 ? total_value / static_cast<double>(visits) : 0.0; }\n};\n\nclass Mcts {\n public:\n  // `cards` backs the Block-A1.5 generic opponent rollout policy (see\n  // generic_opponent.hpp) -- the same static table the V6 scorer already\n  // uses, passed separately because V6Scorer keeps its copy private.\n  Mcts(cg::Engine& engine, const CardTable& cards, const std::vector<int>& deck_const, McTsConfig config)\n      : engine_(engine), deck_const_(deck_const), config_(config), generic_opp_(cards), cards_(cards) {}\n\n  // Returns the chosen option index (into root_obs.options), or -1 if not\n  // even one simulation completed -- caller must fall back to plain V6\n  // greedy (V6Scorer::choose) in that case, exactly like\n  // dragapult_policy_v11.py\'s `_macro_lookahead_choice` returning None.\n  //\n  // CONTRACT: candidate_indices[0] must be V6\'s own greedy pick (the caller\n  // passes candidates sorted by raw greedy score, descending) -- it is the\n  // baseline for the greedy-override margin (stabilization note #3).\n  //\n  // `out_visits`/`out_begin_ok` (both nullable) report search diagnostics\n  // back to the caller (real rollout counts / whether ANY determinization\'s\n  // search_begin succeeded). `out_hit_terminal_reward` (nullable): true if\n  // any rollout\'s RAW value magnitude reached kTerminalRewardThreshold\n  // (i.e. some simulated line genuinely concluded the game).\n  static constexpr double kTerminalRewardThreshold = 500000.0;\n\n  // `out_begin_fail_count`/`out_begin_last_error` (nullable): search_begin\n  // failure diagnostics for the ~9-10%-of-eligible-decisions-never-search\n  // investigation -- how many determinizations\' search_begin calls failed\n  // this decision, and the engine\'s raw error code from the most recent\n  // failure (RawSearchResult::error; -1 = empty reply).\n  // `candidate_raw_scores` (nullable; parallel to candidate_indices): V6\'s\n  // raw greedy scores for the candidates -- B2/PUCT priors. When null,\n  // uniform priors (plain-UCB1-equivalent exploration weighting).\n  int search(const Observation& root_obs, const std::vector<int>& candidate_indices,\n             const std::string& search_begin_input, const V6Scorer& live_scorer,\n             int* out_visits = nullptr, bool* out_begin_ok = nullptr,\n             bool* out_hit_terminal_reward = nullptr, int* out_begin_fail_count = nullptr,\n             int* out_begin_last_error = nullptr,\n             const std::vector<double>* candidate_raw_scores = nullptr) {\n    if (out_visits) *out_visits = 0;\n    if (out_begin_ok) *out_begin_ok = false;\n    if (out_hit_terminal_reward) *out_hit_terminal_reward = false;\n    if (out_begin_fail_count) *out_begin_fail_count = 0;\n    if (out_begin_last_error) *out_begin_last_error = 0;\n    bool hit_terminal = false;\n\n    auto t_start = std::chrono::steady_clock::now();\n    auto elapsed_ms = [&]() {\n      return std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - t_start).count();\n    };\n    const double budget = std::max(0.0, config_.time_budget_ms - config_.safety_buffer_ms);\n    if (candidate_indices.empty()) return -1;\n\n    std::vector<int> my_deck = expand_deck(root_obs);\n    // Defensive padding, same reasoning as expand_deck() below: SearchBegin\'s\n    // native side (Export.cpp\'s CopyIdPtr) copies exactly\n    // `state.players[myIndex].prize.size()` elements out of whatever pointer\n    // we hand it, UNCONDITIONALLY -- a short buffer here is a guaranteed\n    // null/short read (hit empirically against cg.game.battle_start()\'s\n    // local dev harness; see git history of this comment for the full\n    // trace). Never hand the native engine a short buffer for a count it\n    // will unconditionally read.\n    std::vector<int> my_prize = root_obs.myPrizeGuess;\n    while (static_cast<int>(my_prize.size()) < root_obs.myPrizeCount) my_prize.push_back(DETERMINIZATION_FILLER_CARD_ID);\n\n    std::vector<ChildStat> children;\n    children.reserve(candidate_indices.size());\n    for (int idx : candidate_indices) children.push_back(ChildStat{idx, 0, 0.0});\n\n    // B2: softmax priors over V6\'s raw greedy scores (uniform when absent).\n    std::vector<double> priors(children.size(), 1.0 / static_cast<double>(children.size()));\n    if (config_.use_puct && candidate_raw_scores && candidate_raw_scores->size() == children.size()) {\n      double mx = -1e300;\n      for (double s : *candidate_raw_scores) mx = std::max(mx, s);\n      double denom = 0.0;\n      for (size_t i = 0; i < children.size(); ++i) {\n        priors[i] = std::exp(((*candidate_raw_scores)[i] - mx) / config_.puct_prior_temperature);\n        denom += priors[i];\n      }\n      for (double& p : priors) p = std::max(0.02, p / denom);  // floor: no candidate starved outright\n    }\n\n    // B3: per-determinization vote tally (index into children).\n    std::vector<int> det_votes(children.size(), 0);\n    int det_completed = 0;\n\n    int total_visits = 0;\n    bool any_success = false;\n    bool any_begin_ok = false;\n\n    // RAII guard: one search_end() per successful search_begin(), on every\n    // exit path (budget exhaustion mid-determinization, exceptions) -- the\n    // same "search_end() always in a finally block" discipline\n    // dragapult_policy_v11.py documents.\n    struct EndGuard {\n      cg::Engine& e;\n      ~EndGuard() { e.search_end(); }\n    };\n\n    // V20/B1: when use_pwin_eval, simulate_one already returns a value in\n    // [-1, 1] (2*P(win)-1 from the root player\'s perspective, or exactly\n    // +-1/0 for a genuinely concluded game) -- recorded as-is. Legacy path\n    // keeps the tanh squash of the raw heuristic value.\n    std::vector<double> det_value(children.size(), 0.0);  // per-det sums, reset each det (B3)\n    std::vector<int> det_visits(children.size(), 0);\n    auto record = [&](size_t child_i, bool ok, double raw_value) {\n      ChildStat& child = children[child_i];\n      child.visits += 1;\n      total_visits += 1;\n      double v;\n      if (ok) {\n        v = config_.use_pwin_eval ? raw_value : std::tanh(raw_value / kValueSquashScale);\n        any_success = true;\n        if (config_.use_pwin_eval ? (std::fabs(raw_value) >= 0.999)\n                                  : (std::fabs(raw_value) >= kTerminalRewardThreshold)) {\n          hit_terminal = true;\n        }\n      } else {\n        // A candidate whose simulation errors out gets the worst possible\n        // sample (-1, the same floor as a genuine loss) -- stops the\n        // selection loop re-picking a dead branch without conflating a\n        // transient engine hiccup with anything larger than one loss sample.\n        v = -1.0;\n      }\n      child.total_value += v;\n      det_value[child_i] += v;\n      det_visits[child_i] += 1;\n    };\n\n    const int num_det = std::max(1, config_.num_determinizations);\n    for (int det = 0; det < num_det && elapsed_ms() < budget; ++det) {\n      // Stabilization note #2: a FRESH hidden-state sample per\n      // determinization -- statistics accumulate across all of them, so a\n      // candidate\'s mean reflects its value across several sampled worlds,\n      // not one fixed (previously: absurdly passive) one.\n      std::vector<int> opp_deck, opp_prize, opp_hand;\n      sample_opponent_hidden(root_obs, opp_deck, opp_prize, opp_hand);\n      std::vector<int> opp_active;\n      if (!root_obs.oppActive.present || root_obs.oppActive.faceDown) {\n        // Prefer a Basic Pokemon from the archetype pool as the face-down\n        // active guess (Block A1.5 refinement) -- a Grimmsnarl opponent\'s\n        // hidden active should be an Impidimp, not a Dreepy. Falls back to\n        // the original Dreepy filler if the pool has no Basic Pokemon.\n        int guess = DETERMINIZATION_FILLER_POKEMON_ID;\n        for (int cid : root_obs.oppHiddenPool) {\n          const CardData& d = cards_.card(cid);\n          if (d.cardType == enums::CT_POKEMON && d.basic) {\n            guess = cid;\n            break;\n          }\n        }\n        opp_active = {guess};\n      }\n\n      cg::RawSearchResult begin = engine_.search_begin(search_begin_input, my_deck, my_prize, opp_deck,\n                                                        opp_prize, opp_hand, opp_active, /*manual_coin=*/false);\n      if (!begin.ok) {  // a bad sample shouldn\'t kill the whole search; try the next determinization\n        if (out_begin_fail_count) ++(*out_begin_fail_count);\n        if (out_begin_last_error) *out_begin_last_error = begin.error;\n        continue;\n      }\n      any_begin_ok = true;\n      if (out_begin_ok) *out_begin_ok = true;\n      EndGuard end_guard{engine_};\n\n      // Even time slice per determinization (remaining slices absorb any\n      // slack if an earlier begin failed fast).\n      const double det_deadline = std::min(budget, budget * static_cast<double>(det + 1) / static_cast<double>(num_det));\n\n      // B3: fresh per-determinization stats for this world\'s vote.\n      std::fill(det_value.begin(), det_value.end(), 0.0);\n      std::fill(det_visits.begin(), det_visits.end(), 0);\n\n      // Bootstrap: every arm sampled once under THIS determinization before\n      // the selection formula is used on it.\n      for (size_t i = 0; i < children.size(); ++i) {\n        if (elapsed_ms() >= det_deadline) break;\n        double raw = 0.0;\n        bool ok = simulate_one(begin.search_id, root_obs, children[i].option_index, live_scorer, raw);\n        record(i, ok, raw);\n      }\n\n      // Main selection loop for this determinization\'s time slice --\n      // PUCT (B2) when enabled, plain UCB1 otherwise.\n      while (elapsed_ms() < det_deadline && total_visits > 0) {\n        int best = -1;\n        double best_ucb = -1e300;\n        for (size_t i = 0; i < children.size(); ++i) {\n          const ChildStat& c = children[i];\n          double ucb;\n          if (c.visits == 0) {\n            ucb = 1e18;  // never-tried arm still gets tried first\n          } else if (config_.use_puct) {\n            ucb = c.mean() + config_.ucb1_c * priors[i] *\n                                 std::sqrt(static_cast<double>(total_visits)) /\n                                 (1.0 + static_cast<double>(c.visits));\n          } else {\n            ucb = c.mean() + config_.ucb1_c * std::sqrt(std::log(static_cast<double>(total_visits)) /\n                                                         static_cast<double>(c.visits));\n          }\n          if (ucb > best_ucb) {\n            best_ucb = ucb;\n            best = static_cast<int>(i);\n          }\n        }\n        if (best < 0) break;\n        double raw = 0.0;\n        bool ok = simulate_one(begin.search_id, root_obs, children[static_cast<size_t>(best)].option_index,\n                                live_scorer, raw);\n        record(static_cast<size_t>(best), ok, raw);\n      }\n\n      // B3: this determinization\'s vote = best per-det mean among arms it\n      // actually sampled (a det that ran out of time before sampling\n      // anything casts no vote).\n      int det_best = -1;\n      double det_best_mean = -1e300;\n      for (size_t i = 0; i < children.size(); ++i) {\n        if (det_visits[i] > 0) {\n          const double m = det_value[i] / static_cast<double>(det_visits[i]);\n          if (m > det_best_mean) {\n            det_best_mean = m;\n            det_best = static_cast<int>(i);\n          }\n        }\n      }\n      if (det_best >= 0) {\n        det_votes[static_cast<size_t>(det_best)] += 1;\n        det_completed += 1;\n      }\n    }\n\n    if (out_visits) *out_visits = total_visits;\n    if (out_hit_terminal_reward) *out_hit_terminal_reward = hit_terminal;\n    if (!any_begin_ok || !any_success) return -1;\n\n    int best_i = -1;\n    double best_mean = -1e300;\n    for (size_t i = 0; i < children.size(); ++i) {\n      if (children[i].visits > 0 && children[i].mean() > best_mean) {\n        best_mean = children[i].mean();\n        best_i = static_cast<int>(i);\n      }\n    }\n    if (best_i < 0) return -1;\n\n    // B3 (determinization voting): the candidate that wins the per-world\n    // vote MAJORITY replaces the pooled-mean argmax -- robust to one\n    // corrupted/unlucky sampled world dominating the pooled mean. Requires\n    // a strict majority of completed determinizations; otherwise falls back\n    // to the pooled-mean pick.\n    if (config_.use_det_voting && det_completed >= 2) {\n      int vote_best = -1, vote_max = 0;\n      for (size_t i = 0; i < children.size(); ++i) {\n        if (det_votes[i] > vote_max) {\n          vote_max = det_votes[i];\n          vote_best = static_cast<int>(i);\n        }\n      }\n      if (vote_best >= 0 && 2 * vote_max > det_completed) best_i = vote_best;\n      best_mean = children[static_cast<size_t>(best_i)].mean();\n    }\n\n    // Greedy-override margin (stabilization note #3): children[0] is V6\'s\n    // own greedy pick per this function\'s contract. Deviating from it\n    // requires a clear mean advantage on the [-1, 1] value scale --\n    // sampling noise alone (a few hundredths) can no longer flip the\n    // decision away from the known-decent greedy baseline.\n    const ChildStat& greedy = children[0];\n    if (best_i != 0 && greedy.visits > 0 &&\n        (best_mean - greedy.mean()) < config_.greedy_override_margin) {\n      return greedy.option_index;\n    }\n    return children[static_cast<size_t>(best_i)].option_index;\n  }\n\n private:\n  cg::Engine& engine_;\n  const std::vector<int>& deck_const_;\n  McTsConfig config_;\n  GenericOpponentPolicy generic_opp_;  // Block A1.5 opponent rollout policy\n  const CardTable& cards_;\n  std::mt19937 rng_{std::random_device{}()};\n\n  // Filler ids for whatever the sampled pool cannot cover (see\n  // sample_opponent_hidden) -- Basic Fire Energy is always a legal guess,\n  // and the face-down-Active guess must be a real Pokemon id (SearchBegin\n  // requires this).\n  static constexpr int DETERMINIZATION_FILLER_CARD_ID = 2;\n  static constexpr int DETERMINIZATION_FILLER_POKEMON_ID = 119;  // Dreepy\n\n  // Stabilization note #2 + Block A1 (V18): one randomized guess of the\n  // opponent\'s hidden zones. Preferred path: obs.oppHiddenPool -- the\n  // archetype-conditioned pool Python already resolved (classified\n  // archetype\'s canonical 60 minus the opponent\'s visible board AND their\n  // discard -- see opponent_model.py) -- used verbatim, no further\n  // subtraction here. Fallback path (empty pool, defensive only): V17\'s\n  // original mirror assumption, our own DECK constant minus the opponent\'s\n  // visible board. Either way the pool is shuffled fresh per\n  // determinization and dealt to hand/prize/deck at the exact counts\n  // SearchBegin requires; whatever the pool cannot cover falls back to the\n  // energy filler.\n  void sample_opponent_hidden(const Observation& obs, std::vector<int>& opp_deck,\n                              std::vector<int>& opp_prize, std::vector<int>& opp_hand) {\n    std::vector<int> pool;\n    if (!obs.oppHiddenPool.empty()) {\n      pool = obs.oppHiddenPool;\n    } else {\n      pool = deck_const_;\n      auto remove_one = [&](int id) {\n        auto it = std::find(pool.begin(), pool.end(), id);\n        if (it != pool.end()) pool.erase(it);\n      };\n      auto remove_visible = [&](const Pokemon& p) {\n        if (!p.present || p.faceDown) return;\n        remove_one(p.id);\n        for (int eid : p.energyCardIds) remove_one(eid);\n        for (int tid : p.toolIds) remove_one(tid);\n        for (int pid : p.preEvoIds) remove_one(pid);\n      };\n      remove_visible(obs.oppActive);\n      for (const auto& p : obs.oppBench) remove_visible(p);\n    }\n    std::shuffle(pool.begin(), pool.end(), rng_);\n    auto deal = [&](int count) {\n      std::vector<int> out;\n      out.reserve(static_cast<size_t>(std::max(0, count)));\n      for (int i = 0; i < count; ++i) {\n        if (!pool.empty()) {\n          out.push_back(pool.back());\n          pool.pop_back();\n        } else {\n          out.push_back(DETERMINIZATION_FILLER_CARD_ID);\n        }\n      }\n      return out;\n    };\n    opp_hand = deal(obs.oppHandCount);\n    opp_prize = deal(obs.oppPrizeCount);\n    opp_deck = deal(obs.oppDeckCount);\n  }\n\n  // `your_deck` must match our OWN known remaining-deck composition (a real\n  // guess at ORDER, not identity -- see docs/search_api.md §1), which\n  // root_obs.deckCounts already gives us as (id, count) pairs.\n  static std::vector<int> expand_deck(const Observation& obs) {\n    std::vector<int> out;\n    out.reserve(static_cast<size_t>(std::max(0, obs.myDeckCount)));\n    for (const auto& kv : obs.deckCounts) {\n      for (int i = 0; i < kv.second; ++i) out.push_back(kv.first);\n    }\n    // SearchBegin requires an exact count match; pad defensively with the\n    // filler id if our own bookkeeping came up short for any reason.\n    while (static_cast<int>(out.size()) < obs.myDeckCount) out.push_back(DETERMINIZATION_FILLER_CARD_ID);\n    return out;\n  }\n\n  // One full simulation for `option_index`: step it from this\n  // determinization\'s root, then roll out (both sides, driven by a\n  // disposable copy of the live scorer) until the game concludes or the\n  // truncation cap is hit (stabilization note #4), then score the reached\n  // state from the ROOT player\'s perspective. `out_value` is the RAW\n  // state_value() -- the caller squashes it (and checks the terminal\n  // threshold against the raw magnitude) via record(). Returns false on any\n  // engine/parse failure.\n  bool simulate_one(long long root_search_id, const Observation& root_obs, int option_index,\n                     const V6Scorer& live_scorer, double& out_value) {\n    cg::RawSearchResult step = engine_.search_step(root_search_id, std::vector<int>{option_index});\n    if (!step.ok) return false;\n    auto parsed = from_search_json(step.observation_json, root_obs);\n    if (!parsed.has_value()) return false;\n\n    Observation obs = *parsed;\n    recompute_deck_counts(obs, deck_const_);\n\n    // `_rollout_mode` equivalent: a disposable copy so plan_a_/plan_b_/\n    // use_support_ mutations during rollout never touch the live decision-\n    // maker\'s own state (see v6_heuristic.hpp header).\n    V6Scorer scratch = live_scorer;\n\n    long long node_id = step.search_id;\n    int steps = 0;\n    while (steps < config_.max_rollout_steps && obs.result < 0) {\n      // Block A1.5: decisions alternate between players during a rollout\n      // (obs.myIndex tracks whoever is CURRENTLY acting). Our own side keeps\n      // the full V6 scorer; the opponent\'s side uses the deck-agnostic\n      // generic policy (see generic_opponent.hpp\'s header for why V6Scorer\n      // was the wrong driver for foreign-archetype cards).\n      std::vector<int> choice = (obs.myIndex == root_obs.myIndex)\n                                    ? scratch.choose(obs)\n                                    : generic_opp_.choose(obs);\n      cg::RawSearchResult next = engine_.search_step(node_id, choice);\n      if (!next.ok) break;  // evaluate whatever state we already reached\n      auto next_obs = from_search_json(next.observation_json, obs);\n      if (!next_obs.has_value()) break;\n      obs = *next_obs;\n      recompute_deck_counts(obs, deck_const_);\n      node_id = next.search_id;\n      ++steps;\n    }\n\n    if (config_.use_pwin_eval) {\n      // B1: learned P(win) evaluator, mapped to [-1, 1] from the ROOT\n      // player\'s perspective. A genuinely concluded game is scored exactly\n      // (+1 win / -1 loss / 0 draw) -- the model is only consulted for\n      // unresolved positions.\n      if (obs.result >= 0) {\n        out_value = (obs.result == root_obs.myIndex) ? 1.0 : (obs.result == 2 ? 0.0 : -1.0);\n      } else {\n        float features[v20::kVecFeatureCount];\n        v20::vectorize_observation(obs, cards_, features);\n        const double p_acting = v20::pwin_predict(features);\n        // The model predicts for the feature vector\'s ACTING player\n        // (obs.myIndex) -- flip when the rollout ended on an opponent\n        // decision. Trained on both sides of top-level games, so both\n        // directions are in-distribution.\n        const double p_root = (obs.myIndex == root_obs.myIndex) ? p_acting : 1.0 - p_acting;\n        out_value = 2.0 * p_root - 1.0;\n      }\n    } else {\n      out_value = scratch.state_value(obs, root_obs.myIndex);\n    }\n    return true;\n  }\n};\n\n}  // namespace v17\n')
write_source('generic_opponent.hpp', '// Block A1.5: deck-agnostic policy driving the OPPONENT\'s decisions inside\n// MCTS rollouts.\n//\n// Why this exists: A1 (opponent_model.py + oppHiddenPool) gives the simulated\n// opponent the right CARDS, but V17/V18-A1 still drove their DECISIONS with\n// V6Scorer -- a heuristic specialized for OUR Dragapult deck (its hand_score\n// knows our card ids and scores foreign Kangaskhan/Grimmsnarl cards at\n// 0/defaults), so the simulated opponent held the right deck but played it\n// like a confused Dragapult pilot. This policy scores options using only\n// generic signals (damage, KO, prize value, stage, energy counts) available\n// from the C++ CardTable -- a trimmed line-for-line port of\n// src/agents/generic_policy_agent.py\'s band system (the SAME policy that\n// pilots the meta decks in the gauntlet, so rollouts now model the gauntlet\n// opponent with the matching policy class). Trimmings vs the Python original,\n// deliberate: no card-text keyword reads (skill text isn\'t in the C++\n// CardTable; supporters/items get flat in-band scores instead) and no\n// IS_FIRST special case (never occurs mid-rollout).\n//\n// Used ONLY for nodes where the acting player != the root decision-maker\n// (mcts.hpp::simulate_one routes on obs.myIndex) -- our own side keeps the\n// full V6Scorer. Side benefit: the V6 scratch scorer\'s cross-call MAIN-state\n// (plan_a_/plan_b_/use_support_) is no longer polluted by opponent-board\n// decisions, and recompute_deck_counts\' our-deck-minus-their-visible garbage\n// on opponent-perspective nodes (a pre-existing V17 inconsistency) stops\n// influencing anything, since this policy never reads deckCounts.\n#pragma once\n\n#include <algorithm>\n#include <vector>\n\n#include "card_data.hpp"\n#include "observation.hpp"\n#include "v6_heuristic.hpp"  // enums:: + V6Scorer::select_top (static)\n\nnamespace v17 {\n\nnamespace generic_bands {\n// Mirrors generic_policy_agent.py\'s BAND_SCORE exactly.\nconstexpr double kWinningAttack = 1000000.0;\nconstexpr double kPreventLoss = 500000.0;\nconstexpr double kGuaranteedKo = 200000.0;\nconstexpr double kPrizeEfficientAttack = 50000.0;\nconstexpr double kSetupEvolution = 20000.0;\nconstexpr double kEnergyAcceleration = 10000.0;\nconstexpr double kDrawConsistency = 8000.0;\nconstexpr double kBoardDevelopment = 5000.0;\nconstexpr double kFallback = 0.0;\n\n// Option/context ids the v6 enums namespace doesn\'t define (checked against\n// cg/api.py\'s IntEnums).\nconstexpr int OPT_NO = 2, OPT_TOOL_CARD = 4, OPT_DISCARD = 11, OPT_END = 14, OPT_SKILL = 15,\n              OPT_SPECIAL_CONDITION = 16;\nconstexpr int CTX_TO_FIELD = 6;\n}  // namespace generic_bands\n\nclass GenericOpponentPolicy {\n public:\n  explicit GenericOpponentPolicy(const CardTable& cards) : cards_(cards) {}\n\n  std::vector<int> choose(const Observation& obs) const {\n    std::vector<double> scores(obs.options.size(), generic_bands::kFallback);\n    for (size_t i = 0; i < obs.options.size(); ++i) {\n      scores[i] = score_option(obs, obs.options[i]);\n    }\n    return V6Scorer::select_top(obs, scores);\n  }\n\n private:\n  const CardTable& cards_;\n\n  static int prize_value(const CardData& d) { return d.megaEx ? 3 : d.ex ? 2 : 1; }\n\n  // generic_policy_agent.py\'s estimate_damage: base damage with a simple x2\n  // weakness / -20 resistance model (approximate by design -- affects\n  // scoring only, never legality).\n  int estimate_damage(const AttackData& attack, const CardData& attacker, const CardData& defender) const {\n    int dmg = attack.damage;\n    if (defender.weakness >= 0 && defender.weakness == attacker.energyType) dmg *= 2;\n    if (defender.resistance >= 0 && defender.resistance == attacker.energyType) dmg = std::max(0, dmg - 20);\n    return dmg;\n  }\n\n  // Minimal get_card-equivalent for the zones this policy actually scores.\n  // Returns the referenced Pokemon (active/bench zones) or nullptr.\n  const Pokemon* resolve_pokemon(const Observation& obs, int area, int index, int player_index) const {\n    const bool mine = (player_index < 0) || (player_index == obs.myIndex);\n    if (area == enums::AREA_ACTIVE) {\n      const Pokemon& p = mine ? obs.myActive : obs.oppActive;\n      return p.present ? &p : nullptr;\n    }\n    if (area == enums::AREA_BENCH) {\n      const std::vector<Pokemon>& bench = mine ? obs.myBench : obs.oppBench;\n      if (index >= 0 && static_cast<size_t>(index) < bench.size()) return &bench[static_cast<size_t>(index)];\n    }\n    return nullptr;\n  }\n\n  // Card-id resolution for hand/discard/deck-facing/looking/prize zones (the\n  // acting player\'s own zones -- exactly what this policy needs).\n  int resolve_card_id(const Observation& obs, int area, int index) const {\n    auto pick = [&](const std::vector<Card>& zone) -> int {\n      if (index >= 0 && static_cast<size_t>(index) < zone.size()) return zone[static_cast<size_t>(index)].id;\n      return 0;\n    };\n    if (area == enums::AREA_HAND) return pick(obs.myHand);\n    if (area == enums::AREA_DISCARD) return pick(obs.myDiscard);\n    if (area == enums::AREA_DECK) return pick(obs.selectDeck);\n    if (area == enums::AREA_LOOKING) return pick(obs.looking);\n    if (area == enums::AREA_PRIZE) return pick(obs.myPrizeCards);\n    return 0;\n  }\n\n  double score_option(const Observation& obs, const Option& o) const {\n    using namespace generic_bands;\n    const int t = o.type;\n\n    if (t == OPT_END || t == OPT_NO || t == OPT_DISCARD) return kFallback;\n    if (t == enums::OPT_YES) return kSetupEvolution;  // accept beneficial yes/no by default\n\n    if (t == enums::OPT_ATTACK) {\n      const AttackData& attack = cards_.attack(o.attackId);\n      if (!obs.myActive.present || !obs.oppActive.present || attack.attackId == 0) {\n        return kPrizeEfficientAttack;\n      }\n      const CardData& attacker = cards_.card(obs.myActive.id);\n      const CardData& defender = cards_.card(obs.oppActive.id);\n      const int dmg = estimate_damage(attack, attacker, defender);\n      const bool is_ko = dmg >= obs.oppActive.hp;\n      if (is_ko && prize_value(defender) >= obs.myPrizeCount) return kWinningAttack + dmg;\n      if (is_ko) return kGuaranteedKo + dmg;\n      return kPrizeEfficientAttack + dmg;\n    }\n\n    if (t == enums::OPT_RETREAT) {\n      if (obs.myActive.present) {\n        const double hp_frac =\n            static_cast<double>(obs.myActive.hp) / static_cast<double>(std::max(1, obs.myActive.maxHp));\n        if (hp_frac <= 0.34 || obs.myAsleep || obs.myParalyzed || obs.myConfused) return kPreventLoss;\n      }\n      return kFallback - 1.0;\n    }\n\n    if (t == enums::OPT_EVOLVE) {\n      double bonus = 0.0;\n      const int evolved_id = resolve_card_id(obs, o.area, o.index);\n      if (evolved_id != 0) {\n        const CardData& d = cards_.card(evolved_id);\n        bonus = d.stage2 ? 300.0 : d.stage1 ? 150.0 : 0.0;\n      }\n      const Pokemon* target = resolve_pokemon(obs, o.inPlayArea, o.inPlayIndex, obs.myIndex);\n      if (target) bonus += static_cast<double>(target->energies.size());\n      return kSetupEvolution + bonus;\n    }\n\n    if (t == enums::OPT_ATTACH) {\n      double bonus = 0.0;\n      const int card_id = resolve_card_id(obs, o.area, o.index);\n      if (card_id != 0 && cards_.card(card_id).cardType == enums::CT_TOOL) bonus += 500.0;\n      if (o.inPlayArea == enums::AREA_ACTIVE) bonus += 200.0;\n      const Pokemon* target = resolve_pokemon(obs, o.inPlayArea, o.inPlayIndex, obs.myIndex);\n      if (target) bonus -= 50.0 * static_cast<double>(target->energies.size());\n      return kEnergyAcceleration + bonus;\n    }\n\n    if (t == enums::OPT_ABILITY) {\n      if (obs.myDeckCount <= 3) return kFallback;  // deck-out risk\n      return kDrawConsistency;\n    }\n\n    if (t == enums::OPT_PLAY) {\n      const int card_id = resolve_card_id(obs, enums::AREA_HAND, o.index);\n      if (card_id == 0) return kBoardDevelopment;\n      const CardData& d = cards_.card(card_id);\n      if (d.cardType == enums::CT_POKEMON) return kSetupEvolution - 100.0;\n      if (d.cardType == enums::CT_SUPPORTER) return kDrawConsistency + 500.0;\n      if (d.cardType == enums::CT_TOOL) return kBoardDevelopment + 200.0;\n      // stadium / item / energy-as-item: plain board development\n      return kBoardDevelopment;\n    }\n\n    if (t == enums::OPT_CARD) {\n      const int ctx = obs.context;\n      if (ctx == enums::CTX_SWITCH || ctx == enums::CTX_TO_ACTIVE || ctx == enums::CTX_SETUP_ACTIVE_POKEMON) {\n        const Pokemon* p = resolve_pokemon(obs, o.area, o.index, o.playerIndex);\n        if (p && (o.playerIndex < 0 || o.playerIndex == obs.myIndex)) {\n          const CardData& d = cards_.card(p->id);\n          const double stage_bonus = d.stage2 ? 300.0 : d.stage1 ? 150.0 : 0.0;\n          return kSetupEvolution + stage_bonus + p->hp + 50.0 * static_cast<double>(p->energies.size());\n        }\n        // Hand/bench-list selects during setup reference cards, not in-play\n        // Pokemon -- prefer higher-HP basics via the card table.\n        const int card_id = resolve_card_id(obs, o.area, o.index);\n        if (card_id != 0) return kSetupEvolution + cards_.card(card_id).hp;\n        return kFallback;\n      }\n      if (ctx == enums::CTX_SETUP_BENCH_POKEMON || ctx == enums::CTX_TO_BENCH || ctx == generic_bands::CTX_TO_FIELD) {\n        const int card_id = resolve_card_id(obs, o.area, o.index);\n        if (card_id != 0) {\n          const CardData& d = cards_.card(card_id);\n          return kBoardDevelopment + (d.stage2 ? 200.0 : d.stage1 ? 100.0 : 0.0);\n        }\n        return kBoardDevelopment;\n      }\n      if (ctx == enums::CTX_DAMAGE_COUNTER || ctx == enums::CTX_DAMAGE_COUNTER_ANY) {\n        const Pokemon* p = resolve_pokemon(obs, o.area, o.index, o.playerIndex);\n        if (p && o.playerIndex >= 0 && o.playerIndex != obs.myIndex) {\n          return kGuaranteedKo - p->hp + 50.0 * prize_value(cards_.card(p->id));\n        }\n        return kFallback;\n      }\n      if (ctx == enums::CTX_DISCARD) {\n        const int card_id = resolve_card_id(obs, o.area, o.index);\n        if (card_id == 0) return kFallback;\n        const int ct = cards_.card(card_id).cardType;\n        // Least-valuable-first: basic energy < special energy < item < tool <\n        // pokemon/stadium < supporter (generic_policy_agent.py\'s rank table).\n        int rank = 3;\n        if (ct == enums::CT_BASIC_ENERGY) rank = 0;\n        else if (ct == enums::CT_SPECIAL_ENERGY) rank = 1;\n        else if (ct == enums::CT_TOOL) rank = 3;\n        else if (ct == enums::CT_POKEMON) rank = 4;\n        else if (ct == enums::CT_SUPPORTER) rank = 5;\n        else rank = 2;  // item / stadium-as-item flows\n        return kFallback + (5 - rank) * 10.0;\n      }\n      if (ctx == enums::CTX_ATTACH_FROM) {\n        const Pokemon* p = resolve_pokemon(obs, o.area, o.index, o.playerIndex);\n        if (p) return kEnergyAcceleration - 50.0 * static_cast<double>(p->energies.size());\n        return kEnergyAcceleration;\n      }\n      if (ctx == enums::CTX_TO_HAND) return kDrawConsistency;\n      return kFallback;\n    }\n\n    if (t == enums::OPT_ENERGY || t == enums::OPT_ENERGY_CARD || t == generic_bands::OPT_TOOL_CARD) {\n      return kEnergyAcceleration;\n    }\n    if (t == enums::OPT_NUMBER) return static_cast<double>(std::max(0, o.number));\n    if (t == generic_bands::OPT_SKILL) return kDrawConsistency;\n    if (t == generic_bands::OPT_SPECIAL_CONDITION) return kPreventLoss;\n\n    return kFallback;  // unmodeled option type: safe neutral, never a crash\n  }\n};\n\n}  // namespace v17\n')
